INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C1','kor',2,1,'u5',1,'마음 짐작의 뜻과 단서 — 다른 사람의 말·행동·표정·상황을 보고 어떤 마음인지 헤아리는 것이 마음 짐작이며, 마음을 헤아리면 친구를 더 잘 이해하고 배려할 수 있음을 알기',ARRAY['2국02-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C2','kor',2,1,'u5',1,'뜻이 드러나게 띄어 읽기 — 붙여 읽으면 뜻을 알기 어렵고, 「누가(무엇이)」에 해당하는 말 뒤처럼 뜻이 통하는 덩어리 사이에서 쉬어 읽으면 뜻이 잘 드러남을 알기(아빠가 / 방에 / 들어가신다)',ARRAY['2국02-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C3','kor',2,1,'u5',3,'말과 행동으로 인물의 마음 짐작하기 — 글 속 인물에게 일어난 일을 살피고, 마음이 드러난 말(「드디어 됐다!」)과 행동(두 손을 번쩍)을 찾아 까닭을 들어 마음을 짐작하기',ARRAY['2국02-04']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C4','kor',2,1,'u5',3,'상황으로 마음 짐작하고 나와 견주기 — 소풍 날 비가 오는 것처럼 인물이 놓인 상황으로 마음을 짐작하고, 「나라면 어떤 마음일까」 비슷한 경험과 견주며, 같은 일에도 사람마다 마음이 다를 수 있음을 알기',ARRAY['2국02-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C5','kor',2,1,'u5',3,'마음을 나타내는 말 — 기쁘다·설레다·뿌듯하다·고맙다·속상하다·서운하다·아쉽다·미안하다·억울하다·떨리다 같은 말의 뜻을 알고, 상황에 어울리는 마음 말을 고르기',ARRAY['2국02-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C6','kor',2,1,'u5',5,'시간에 따라 변하는 마음 따라 읽기 — 일이 일어난 차례를 따라가며 장면마다 인물의 마음을 짐작하고, 무엇 때문에 마음이 바뀌었는지 말하기(낯설고 떨림 → 고맙고 반가움 → 즐거움)',ARRAY['2국02-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C7','kor',2,1,'u5',7,'헷갈리기 쉬운 낱말 가려 쓰기 — 소리가 같거나 비슷해도 뜻이 다른 낱말(걸음·거름, 마치다·맞히다, 다치다·닫히다, 반듯이·반드시)과 뜻이 헷갈리는 낱말(가르치다·가리키다, 다르다·틀리다, 바라다·바래다, 잊다·잃다)을 문장의 뜻을 생각하며 바르게 골라 쓰기',ARRAY['2국04-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C8','kor',2,1,'u5',9,'자연스럽게 띄어 읽기 — 낱말마다 뚝뚝 끊거나 쉬지 않고 붙여 읽지 않고, 의미가 통하는 덩어리로 쉬며, 문장과 문장 사이에서는 조금 더 길게 쉬어 물 흐르듯 읽기(띄어 읽을 곳에 빗금 표시)',ARRAY['2국02-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C9','kor',2,1,'u5',9,'인물의 마음을 살려 읽기 — 기쁜 장면은 밝고 가볍게, 슬픈 장면은 차분하고 느리게, 떨리는 장면은 작고 조심스럽게 — 알맞게 띄어 읽으면서 인물의 마음에 맞게 목소리를 바꾸어 읽기',ARRAY['2국02-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-1-u5-C10','kor',2,1,'u5',11,'마음을 나타내는 말로 전하고 헤아리기 — 마음 사전(마음 말 + 그 마음이 드는 상황)을 만들고, 「기분 나빠」 대신 「네 말에 서운했어」처럼 마음 말로 정확히 전하며, 친구의 마음 말에는 「속상했겠다」처럼 마음을 헤아린 맞장구로 반응하기',ARRAY['2국02-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X01','kor',2,'u5',ARRAY['K2-1-u5-C1','K2-1-u5-C3']::text[],'마음과 상관없는 것(생김새·옷·키·이름)으로 마음을 짐작하거나, 까닭 없이 「그냥」 짐작한다','말·행동·표정·상황 가운데 무엇을 보고 알았는지 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X02','kor',2,'u5',ARRAY['K2-1-u5-C1','K2-1-u5-C3']::text[],'말·행동·표정이 보여 주는 마음을 거꾸로 읽는다(고개를 푹 숙임 → 신남, 두 손을 번쩍 → 속상함)','그 행동을 직접 따라 해 보며 어떤 기분이 드는지 느끼기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X03','kor',2,'u5',ARRAY['K2-1-u5-C4']::text[],'인물이 놓인 상황을 살피지 않고 엉뚱한 마음을 고른다(기다리던 소풍 날 비가 옴 → 신남)','「무슨 일이 있었지?」 먼저 말해 보고 마음 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X04','kor',2,'u5',ARRAY['K2-1-u5-C4','K2-1-u5-C1']::text[],'인물 대신 지금 내 기분대로 짐작하거나, 같은 일이면 누구나 똑같은 마음이라고 여긴다(형과 동생 마음을 바꿔 앎)','「그 자리에 있는 사람은 누구지? 그 사람이라면?」 하고 사람마다 나눠 생각하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X05','kor',2,'u5',ARRAY['K2-1-u5-C5','K2-1-u5-C10']::text[],'마음을 나타내지 않는 낱말(책상·운동장·연필·달리다)을 마음 말로 여긴다','「나는 지금 ○○해.」에 넣어 말이 되는지 해 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X06','kor',2,'u5',ARRAY['K2-1-u5-C5','K2-1-u5-C10']::text[],'마음 말의 뜻을 바꿔 알거나 상황에 맞지 않는 마음 말을 쓴다(소풍 전날 → 서운하다, 약속을 어김 → 설레다)','그 마음 말이 드는 때를 하나 떠올려 보고 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X07','kor',2,'u5',ARRAY['K2-1-u5-C6','K2-1-u5-C3']::text[],'인물의 마음이 처음부터 끝까지 그대로라고 여기거나, 마음이 바뀐 차례를 뒤바꾼다','「처음 → 무슨 일 → 나중」 세 칸에 마음을 하나씩 적어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X08','kor',2,'u5',ARRAY['K2-1-u5-C3','K2-1-u5-C6']::text[],'글에 없는 내용을 있다고 하거나 글의 내용을 놓친다','글에서 그 문장을 찾아 손가락으로 짚어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X09','kor',2,'u5',ARRAY['K2-1-u5-C7']::text[],'소리가 같으면 뜻을 생각하지 않고 아무 낱말이나·소리 나는 대로 쓴다(텃밭에 걸음을 주다, 수업을 맞혔다, 무릎을 닫혔다, 반듯이 숙제를 하다)','문장의 뜻을 말로 풀어 보고(「꼭」이야? 「곧게」야?) 낱말 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X10','kor',2,'u5',ARRAY['K2-1-u5-C7']::text[],'뜻이 헷갈리는 낱말을 바꿔 쓴다(가르치다↔가리키다, 다르다↔틀리다, 잊다↔잃다, 바라다↔바래다)','낱말 짝의 뜻을 하나씩 말해 보고 문장에 넣어 견주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X11','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C8']::text[],'낱말마다·한 글자씩 뚝뚝 끊어 읽어 뜻이 드러나지 않는다(토 / 끼 / 가 / 풀밭에서)','뜻이 이어지는 말끼리 손으로 묶어 보고 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X12','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C8']::text[],'쉬지 않고 붙여 읽거나 빨리 읽기만 하면 잘 읽은 것이라 여긴다(숨이 차고 뜻을 알기 어려움)','「누가(무엇이)」 뒤에서 한 번 숨 쉬기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X13','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C8']::text[],'엉뚱한 곳에서 끊어 읽어 뜻이 바뀌게 한다(아빠가방에 / 들어가신다, 나물 / 좀 주세요 ↔ 나 / 물 좀 주세요)','끊어 읽은 대로 그림을 떠올려 보고 뜻이 맞는지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X14','kor',2,'u5',ARRAY['K2-1-u5-C2','K2-1-u5-C8']::text[],'쉬는 길이를 가리지 못한다(문장과 문장 사이에서 더 길게 쉬지 않음, 「/」에서 쉬지 않음)','「/」 한 번 숨, 문장이 끝나면 한 번 더 — 손뼉으로 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X15','kor',2,'u5',ARRAY['K2-1-u5-C9']::text[],'인물의 마음과 맞지 않는 목소리로 읽거나 모든 장면을 한 가지 목소리로 읽는다(슬픈 장면을 신나게)','「지금 인물은 어떤 마음이지?」 먼저 말하고 목소리 정하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X16','kor',2,'u5',ARRAY['K2-1-u5-C10']::text[],'마음을 뭉뚱그린 말·마음이 담기지 않은 말로 전하거나(「기분 나빠」·「몰라, 됐어」), 친구의 마음을 헤아리지 않고 대꾸한다(놀리기·탓하기·딴소리)','「내가 그 말을 들으면 어떤 마음일까?」 떠올리고 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-1-u5-X17','kor',2,'u5',ARRAY['K2-1-u5-C1','K2-1-u5-C3','K2-1-u5-C4','K2-1-u5-C5','K2-1-u5-C6','K2-1-u5-C7','K2-1-u5-C8','K2-1-u5-C9','K2-1-u5-C10']::text[],'묻는 말을 거꾸로 읽는다 — 잘못↔바르게, 알맞지 않은↔알맞은, 어색한↔자연스러운','물음의 「잘못·않은·어색한」에 동그라미를 치고 답을 넣어 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#1','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',1,'mc','auto','다른 사람의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X01']::text[],true,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"다른 사람의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"말 · 행동 · 표정 · 상황","correct":true},{"t":"옷 색깔 · 키 · 신발","mis":"K2-1-u5-X01"},{"t":"이름 · 나이 · 머리 모양","mis":"K2-1-u5-X01"}],"explanation":["마음은 말·행동·표정·상황에서 드러나요.","옷 색깔이나 이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어 말해요."],"variant_rule":{"alt":[{"stem":"다른 사람의 마음을 짐작하는 것을 바르게 말한 것은 어느 것인가요?","options":[{"t":"말과 행동, 표정을 보고 어떤 마음인지 헤아리는 것","correct":true},{"t":"얼굴 생김새를 보고 이름을 맞히는 것","mis":"K2-1-u5-X01"},{"t":"그 사람의 키를 재어 보는 것","mis":"K2-1-u5-X01"}],"explanation":["마음 짐작은 말·행동·표정·상황을 보고 마음을 헤아리는 거예요.","생김새나 키는 마음과 상관없어요.","마음을 헤아리면 친구를 더 잘 이해할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#2','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',1,'mc','auto','친구가 활짝 웃으며 깡충깡충 뛰고 있어요. 친구는 어떤 마음일까요?',ARRAY['K2-1-u5-X02']::text[],true,'{"seq":2,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"친구가 활짝 웃으며 깡충깡충 뛰고 있어요. 친구는 어떤 마음일까요?","options":[{"t":"기쁜 마음","correct":true},{"t":"속상한 마음","mis":"K2-1-u5-X02"},{"t":"무서운 마음","mis":"K2-1-u5-X02"}],"explanation":["활짝 웃으며 뛰는 모습에서 기쁜 마음이 드러나요.","속상하거나 무서우면 웃으며 뛰지 않아요.","표정과 행동을 보고 마음을 짐작해요."],"variant_rule":{"alt":[{"stem":"친구가 넘어져서 고개를 푹 숙이고 있어요. 친구는 어떤 마음일까요?","options":[{"t":"아프고 속상한 마음","correct":true},{"t":"신나고 즐거운 마음","mis":"K2-1-u5-X02"},{"t":"뿌듯하고 자랑스러운 마음","mis":"K2-1-u5-X02"}],"explanation":["넘어져서 고개를 숙인 모습에서 아프고 속상한 마음이 드러나요.","신나거나 뿌듯하면 고개를 숙이지 않아요.","표정과 행동을 보고 마음을 짐작해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#3','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],true,'{"seq":3,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「동생이 / 우유를 / 마신다」","correct":true},{"t":"「동 / 생이우 / 유를 마신다」","mis":"K2-1-u5-X11"},{"t":"「동생이우유를마신다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「하늘에 / 무지개가 / 떴다」","correct":true},{"t":"「하 / 늘에무 / 지개가 떴다」","mis":"K2-1-u5-X11"},{"t":"「하늘에무지개가떴다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#4','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C2',1,'ox','auto','문장을 쉬지 않고 붙여 읽으면 뜻이 더 잘 드러나요.',ARRAY['K2-1-u5-X12']::text[],true,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"ox","stem":"문장을 쉬지 않고 붙여 읽으면 뜻이 더 잘 드러나요.","answer":"X","reason_options":[{"t":"뜻이 통하는 덩어리로 쉬어 읽어야 뜻이 잘 드러나니까","correct":true},{"t":"빨리 읽어야 잘 읽은 것이니까","mis":"K2-1-u5-X12"}],"mis":"K2-1-u5-X12","explanation":["붙여 읽으면 듣는 사람이 뜻을 알기 어려워요.","뜻이 통하는 덩어리로 쉬어 읽어요.","빨리 읽는 것과 잘 읽는 것은 달라요."],"variant_rule":{"alt":[{"stem":"「누가(무엇이)」에 해당하는 말 뒤에서 조금 쉬어 읽으면 뜻이 잘 드러나요.","answer":"O","reason_options":[{"t":"「동생이 / 우유를 마신다」처럼 뜻 덩어리가 나뉘니까","correct":true},{"t":"쉬지 않고 읽어야 뜻이 드러나니까","mis":"K2-1-u5-X12"}],"explanation":["「누가(무엇이)」 뒤에서 쉬면 뜻 덩어리가 나뉘어요.","듣는 사람이 뜻을 잘 알아들어요.","쉬지 않으면 숨이 차고 알아듣기 어려워요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#5','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"생일 선물을 받았을 때","r":"기쁘다"},{"l":"아끼던 장난감이 부서졌을 때","r":"속상하다"},{"l":"내일 소풍을 가기로 했을 때","r":"설레다"}],"mis":"K2-1-u5-X03","explanation":["선물을 받으면 기쁜 마음이 들어요.","아끼던 장난감이 부서지면 속상해요.","내일 소풍을 간다면 설레는 마음이 들어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"친구가 넘어진 나를 일으켜 주었을 때","r":"고맙다"},{"l":"내가 친구 발을 밟았을 때","r":"미안하다"},{"l":"발표 차례를 기다릴 때","r":"떨리다"}],"explanation":["도움을 받으면 고마운 마음이 들어요.","친구 발을 밟으면 미안한 마음이 들어요.","발표 차례를 기다리면 떨리는 마음이 들어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#6','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C5',2,'mc','auto','마음을 나타내는 말만 모은 것은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],true,'{"seq":6,"concept":"K2-1-u5-C5","difficulty":2,"kind":"mc","stem":"마음을 나타내는 말만 모은 것은 어느 것인가요?","options":[{"t":"기쁘다 · 설레다 · 고맙다","correct":true},{"t":"기쁘다 · 책상 · 고맙다","mis":"K2-1-u5-X05"},{"t":"운동장 · 연필 · 의자","mis":"K2-1-u5-X05"}],"explanation":["「기쁘다」·「설레다」·「고맙다」는 모두 마음을 나타내요.","「책상」·「운동장」·「연필」·「의자」는 물건이나 장소의 이름이에요.","「나는 지금 ○○해.」에 넣어 말이 되는지 해 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 마음을 나타내는 말만 모은 것은 어느 것인가요?","options":[{"t":"속상하다 · 뿌듯하다 · 미안하다","correct":true},{"t":"속상하다 · 달리다 · 미안하다","mis":"K2-1-u5-X05"},{"t":"가방 · 학교 · 칠판","mis":"K2-1-u5-X05"}],"explanation":["「속상하다」·「뿌듯하다」·「미안하다」는 모두 마음을 나타내요.","「달리다」는 움직임, 「가방」·「학교」·「칠판」은 물건이나 장소예요.","「나는 지금 ○○해.」에 넣어 말이 되는지 해 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#7','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C4',2,'mc','auto','누나가 정성껏 그린 그림에 동생이 실수로 물을 엎질렀어요. 누나는 어떤 마음일까요?',ARRAY['K2-1-u5-X03']::text[],true,'{"seq":7,"concept":"K2-1-u5-C4","difficulty":2,"kind":"mc","stem":"누나가 정성껏 그린 그림에 동생이 실수로 물을 엎질렀어요. 누나는 어떤 마음일까요?","options":[{"t":"속상한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u5-X03"},{"t":"졸린 마음","mis":"K2-1-u5-X03"}],"explanation":["정성껏 그린 그림이 젖으면 속상한 마음이 들어요.","신나거나 졸린 마음은 이 상황과 맞지 않아요.","무슨 일이 있었는지 먼저 살펴요."],"variant_rule":{"alt":[{"stem":"기다리던 현장 체험학습 날 아침이에요. 가방을 메고 집을 나서는 친구는 어떤 마음일까요?","options":[{"t":"설레고 신나는 마음","correct":true},{"t":"서운하고 슬픈 마음","mis":"K2-1-u5-X03"},{"t":"미안하고 부끄러운 마음","mis":"K2-1-u5-X03"}],"explanation":["기다리던 날이 오면 설레고 신나는 마음이 들어요.","서운하거나 미안한 마음은 이 상황과 맞지 않아요.","무슨 일이 있었는지 먼저 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#8','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C2',2,'sa','auto','「아빠가방에들어가신다」를 「아빠가 / 방에 / 들어가신다」로 띄어 읽었어요. 아빠가 들어가신 곳은 어디인가요? 한 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C2","difficulty":2,"kind":"sa","stem":"「아빠가방에들어가신다」를 「아빠가 / 방에 / 들어가신다」로 띄어 읽었어요. 아빠가 들어가신 곳은 어디인가요? 한 글자로 써 보세요.","answer":["방"],"explanation":["「아빠가 / 방에」로 띄어 읽으면 아빠가 방에 들어가신 거예요.","「아빠 / 가방에」로 끊으면 가방에 들어가는 뜻이 돼요.","어디에서 쉬느냐에 따라 뜻이 달라져요."],"variant_rule":{"alt":[{"stem":"「나물 좀 주세요」를 「나물 / 좀 주세요」로 띄어 읽었어요. 달라고 한 것은 무엇인가요? 두 글자로 써 보세요.","answer":["나물"],"explanation":["「나물 / 좀 주세요」는 나물을 달라는 뜻이에요.","「나 / 물 좀 주세요」로 끊으면 물을 달라는 뜻이 돼요.","어디에서 쉬느냐에 따라 뜻이 달라져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#9','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',2,'mc','auto','다른 사람의 마음을 짐작하면 어떤 점이 좋을까요?',ARRAY['K2-1-u5-X01','K2-1-u5-X04']::text[],true,'{"seq":9,"concept":"K2-1-u5-C1","difficulty":2,"kind":"mc","stem":"다른 사람의 마음을 짐작하면 어떤 점이 좋을까요?","options":[{"t":"친구를 더 잘 이해하고 배려할 수 있어요","correct":true},{"t":"친구의 키를 알 수 있어요","mis":"K2-1-u5-X01"},{"t":"친구 마음과 상관없이 내 마음대로 해도 돼요","mis":"K2-1-u5-X04"}],"explanation":["마음을 헤아리면 친구를 이해하고 배려할 수 있어요.","키는 마음과 상관없어요.","내 마음대로가 아니라 친구 마음을 생각해요."],"variant_rule":{"alt":[{"stem":"말하지 않아도 친구의 마음을 알 수 있는 까닭은 무엇인가요?","options":[{"t":"표정과 행동에 마음이 드러나니까","correct":true},{"t":"친구의 옷에 마음이 쓰여 있으니까","mis":"K2-1-u5-X01"},{"t":"누구나 언제나 나와 같은 마음이니까","mis":"K2-1-u5-X04"}],"explanation":["웃는 얼굴, 숙인 고개처럼 표정과 행동에 마음이 드러나요.","옷에 마음이 쓰여 있지 않아요.","사람마다 마음이 다를 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_basic#10','kor',2,1,'u5','L01','g2_1_kor_u5_L01_basic','lesson_basic','K2-1-u5-C1',3,'error','auto','「상을 받고 두 손을 번쩍 들었어요.」를 읽고 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C1","difficulty":3,"kind":"error","stem":"「상을 받고 두 손을 번쩍 들었어요.」를 읽고 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"시우 — 「부끄럽고 미안한 마음이야.」","correct":true,"mis_target":"K2-1-u5-X02"},{"t":"다은 — 「기쁜 마음이야.」","mis":"K2-1-u5-X17"},{"t":"로아 — 「뿌듯한 마음이야.」","mis":"K2-1-u5-X17"}],"explanation":["두 손을 번쩍 드는 행동은 기쁘고 뿌듯한 마음을 보여 줘요.","부끄럽고 미안하면 고개를 숙이거나 얼굴을 가려요.","다은이와 로아는 알맞게 짐작했어요."],"variant_rule":{"alt":[{"stem":"「친구가 다가오자 빙긋 웃었어요.」를 읽고 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"준우 — 「화가 나서 싫은 마음이야.」","correct":true,"mis_target":"K2-1-u5-X02"},{"t":"하린 — 「반가운 마음이야.」","mis":"K2-1-u5-X17"},{"t":"지안 — 「좋은 마음이야.」","mis":"K2-1-u5-X17"}],"explanation":["빙긋 웃는 표정은 반갑고 좋은 마음을 보여 줘요.","화가 나면 얼굴을 찡그리거나 돌아서요.","하린이와 지안이는 알맞게 짐작했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#1','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C4',2,'mc','auto','언니가 쌓은 블록 탑을 동생이 실수로 무너뜨렸어요. 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":1,"concept":"K2-1-u5-C4","difficulty":2,"kind":"mc","stem":"언니가 쌓은 블록 탑을 동생이 실수로 무너뜨렸어요. 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"언니는 속상하고, 동생은 미안해요","correct":true},{"t":"언니는 미안하고, 동생은 속상해요","mis":"K2-1-u5-X04"},{"t":"언니는 신나고, 동생은 뿌듯해요","mis":"K2-1-u5-X03"}],"explanation":["탑이 무너진 언니는 속상하고, 무너뜨린 동생은 미안할 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#2','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',2,'mc','auto','문장을 띄어 읽을 때 쉬어 읽기 좋은 곳은 어디인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":2,"concept":"K2-1-u5-C2","difficulty":2,"kind":"mc","stem":"문장을 띄어 읽을 때 쉬어 읽기 좋은 곳은 어디인가요?","options":[{"t":"「누가(무엇이)」에 해당하는 말 뒤","correct":true},{"t":"낱말의 한가운데","mis":"K2-1-u5-X11"},{"t":"아무 곳이나 숨이 찰 때","mis":"K2-1-u5-X13"}],"explanation":["「동생이 / 우유를 마신다」처럼 「누가」 뒤에서 쉬어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","아무 데서나 쉬면 뜻이 바뀔 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#3','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',3,'mc','auto','물을 달라는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X13','K2-1-u5-X12']::text[],false,'{"seq":3,"concept":"K2-1-u5-C2","difficulty":3,"kind":"mc","stem":"물을 달라는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「나 / 물 좀 주세요」","correct":true},{"t":"「나물 / 좀 주세요」","mis":"K2-1-u5-X13"},{"t":"「나물좀주세요」","mis":"K2-1-u5-X12"}],"explanation":["「나 / 물 좀 주세요」로 읽어야 물을 달라는 뜻이 돼요.","「나물 / 좀 주세요」는 나물을 달라는 뜻이에요.","띄어 읽는 곳에 따라 뜻이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#4','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C1',3,'error','auto','「친구가 다가오자 빙긋 웃었어요.」를 읽고 마음을 짐작한 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X01','K2-1-u5-X17']::text[],false,'{"seq":4,"concept":"K2-1-u5-C1","difficulty":3,"kind":"error","stem":"「친구가 다가오자 빙긋 웃었어요.」를 읽고 마음을 짐작한 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「그냥 화난 것 같아. 까닭은 없어.」","correct":true,"mis_target":"K2-1-u5-X01"},{"t":"예린 — 「빙긋 웃었으니 반가운 마음이야.」","mis":"K2-1-u5-X17"},{"t":"하늘 — 「친구가 다가와서 좋은 마음이야.」","mis":"K2-1-u5-X17"}],"explanation":["마음을 짐작할 때는 표정·행동 같은 까닭을 들어야 해요.","빙긋 웃는 표정은 화난 마음이 아니에요.","예린이와 하늘이는 까닭을 들어 알맞게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#5','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C4',3,'ox','auto','「소풍 가는 날 아침에 비가 내려 소풍이 미뤄졌어요.」 소풍을 기다리던 친구는 신나고 기쁜 마음일 거예요.',ARRAY['K2-1-u5-X03']::text[],false,'{"seq":5,"concept":"K2-1-u5-C4","difficulty":3,"kind":"ox","stem":"「소풍 가는 날 아침에 비가 내려 소풍이 미뤄졌어요.」 소풍을 기다리던 친구는 신나고 기쁜 마음일 거예요.","answer":"X","reason_options":[{"t":"기다리던 소풍을 못 가게 되어 아쉽고 속상할 테니까","correct":true},{"t":"비가 오면 누구나 신나니까","mis":"K2-1-u5-X03"}],"mis":"K2-1-u5-X03","explanation":["기다리던 소풍이 미뤄지면 아쉽고 속상해요.","상황을 살피면 마음을 짐작할 수 있어요.","무슨 일이 있었는지 먼저 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#6','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C5',3,'mc','auto','「아끼던 필통을 잃어버렸어요.」에 어울리는 마음 말은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":6,"concept":"K2-1-u5-C5","difficulty":3,"kind":"mc","stem":"「아끼던 필통을 잃어버렸어요.」에 어울리는 마음 말은 어느 것인가요?","options":[{"t":"속상하다","correct":true},{"t":"설레다","mis":"K2-1-u5-X06"},{"t":"뿌듯하다","mis":"K2-1-u5-X06"}],"explanation":["아끼던 물건을 잃어버리면 속상한 마음이 들어요.","「설레다」는 기대될 때, 「뿌듯하다」는 해냈을 때의 마음이에요.","그 마음 말이 드는 때를 떠올려 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#7','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',3,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X13','K2-1-u5-X11']::text[],false,'{"seq":7,"concept":"K2-1-u5-C2","difficulty":3,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「키가 큰 기린이 / 높은 나뭇잎을 / 먹어요」","correct":true},{"t":"「키가 큰기 / 린이높은 / 나뭇잎을 먹어요」","mis":"K2-1-u5-X13"},{"t":"「키 / 가 / 큰 / 기 / 린이 / 높은 / 나뭇잎을」","mis":"K2-1-u5-X11"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","「큰기 / 린이」처럼 끊으면 뜻이 흐려져요.","한 글자씩 끊으면 뜻이 드러나지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#8','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C1',4,'mc','auto','다른 사람의 마음을 짐작하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X01','K2-1-u5-X04']::text[],false,'{"seq":8,"concept":"K2-1-u5-C1","difficulty":4,"kind":"mc","stem":"다른 사람의 마음을 짐작하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말·행동·상황을 살피고, 내가 그 자리라면 어떨지 떠올려요","correct":true},{"t":"그 사람의 생김새만 보고 정해요","mis":"K2-1-u5-X01"},{"t":"지금 내 기분과 똑같다고 정해요","mis":"K2-1-u5-X04"}],"explanation":["말·행동·상황을 살피고 나라면 어떨지 견주어 봐요.","생김새는 마음을 알려 주지 않아요.","내 기분이 아니라 그 사람의 자리에서 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#9','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C1',4,'essay','teacher','가족이나 친구의 마음을 짐작해 본 일을 떠올려, 무엇을 보고 어떤 마음이라고 짐작했는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C1","difficulty":4,"kind":"essay","stem":"가족이나 친구의 마음을 짐작해 본 일을 떠올려, 무엇을 보고 어떤 마음이라고 짐작했는지 써 보세요.","answer_guide":{"answer":"예: 동생이 받아쓰기 공책을 가방에 넣고 고개를 숙이고 있었어요. 그걸 보고 받아쓰기를 잘 못 봐서 속상한 마음이라고 짐작했어요.","scoring_points":["누구의 마음을 짐작했는지 썼는가","무엇(말·행동·표정·상황)을 보고 짐작했는지 썼는가","짐작한 마음을 마음 말로 썼는가"]},"explanation":["누구의 마음.","짐작한 까닭.","마음 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L01_challenge#10','kor',2,1,'u5','L01','g2_1_kor_u5_L01_challenge','lesson_challenge','K2-1-u5-C2',4,'essay','teacher','「아기다람쥐가나무에올라가요」를 낱말을 띄어 바르게 옮겨 쓰고, 뜻이 잘 드러나게 띄어 읽을 곳에 「/」를 넣어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C2","difficulty":4,"kind":"essay","stem":"「아기다람쥐가나무에올라가요」를 낱말을 띄어 바르게 옮겨 쓰고, 뜻이 잘 드러나게 띄어 읽을 곳에 「/」를 넣어 써 보세요.","answer_guide":{"answer":"예: 아기 다람쥐가 나무에 올라가요. → 아기 다람쥐가 / 나무에 올라가요.","scoring_points":["낱말 사이를 띄어 바르게 옮겨 썼는가","「누가(무엇이)」 뒤처럼 알맞은 곳에 「/」를 넣었는가","낱말 가운데를 끊지 않았는가"]},"explanation":["바르게 옮겨 쓰기.","알맞은 곳에 「/」.","뜻 덩어리 지키기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#1','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',1,'mc','auto','글을 읽고 답해 보세요. 서준이가 「와, 해냈다!」 하며 손뼉을 쳤을 때의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],true,'{"seq":1,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이가 「와, 해냈다!」 하며 손뼉을 쳤을 때의 마음은 어느 것인가요?","options":[{"t":"기쁘고 뿌듯한 마음","correct":true},{"t":"슬프고 외로운 마음","mis":"K2-1-u5-X02"},{"t":"무섭고 떨리는 마음","mis":"K2-1-u5-X02"}],"explanation":["「와, 해냈다!」라는 말과 손뼉을 치는 행동에서 기쁘고 뿌듯한 마음이 드러나요.","슬프거나 무서우면 손뼉을 치지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 동생이 고개를 숙이고 「언니, 미안해.」 했을 때 동생의 마음은 어느 것인가요?","options":[{"t":"미안한 마음","correct":true},{"t":"뿌듯한 마음","mis":"K2-1-u5-X02"},{"t":"신나는 마음","mis":"K2-1-u5-X02"}],"explanation":["고개를 숙이고 「미안해.」라고 한 말과 행동에서 미안한 마음이 드러나요.","뿌듯하거나 신나면 고개를 숙이지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#2','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',1,'mc','auto','글을 읽고 답해 보세요. 비행기가 바닥에 툭 떨어지자 서준이는 입술을 삐죽 내밀었어요. 이때 서준이의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],true,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 비행기가 바닥에 툭 떨어지자 서준이는 입술을 삐죽 내밀었어요. 이때 서준이의 마음은 어느 것인가요?","options":[{"t":"속상한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u5-X02"},{"t":"고마운 마음","mis":"K2-1-u5-X02"}],"explanation":["입술을 삐죽 내미는 행동에서 속상한 마음이 드러나요.","신나거나 고마우면 입술을 삐죽 내밀지 않아요.","행동을 따라 해 보며 마음을 느껴요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 카드에 우유가 쏟아지자 지우는 눈물이 핑 돌았어요. 이때 지우의 마음은 어느 것인가요?","options":[{"t":"속상한 마음","correct":true},{"t":"설레는 마음","mis":"K2-1-u5-X02"},{"t":"뿌듯한 마음","mis":"K2-1-u5-X02"}],"explanation":["눈물이 핑 도는 모습에서 속상한 마음이 드러나요.","설레거나 뿌듯하면 눈물이 핑 돌지 않아요.","행동을 따라 해 보며 마음을 느껴요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#3','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',1,'ox','auto','글 속 인물의 마음은 인물의 말과 행동을 보고 짐작할 수 있어요.',ARRAY['K2-1-u5-X01']::text[],true,'{"seq":3,"concept":"K2-1-u5-C3","difficulty":1,"kind":"ox","stem":"글 속 인물의 마음은 인물의 말과 행동을 보고 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"마음이 말과 행동에 드러나니까","correct":true},{"t":"인물의 마음은 생김새로만 알 수 있으니까","mis":"K2-1-u5-X01"}],"mis":"K2-1-u5-X01","explanation":["「드디어 됐다!」 같은 말이나 두 손을 번쩍 드는 행동에 마음이 드러나요.","생김새는 마음을 알려 주지 않아요.","마음이 드러난 말과 행동을 찾아요."],"variant_rule":{"alt":[{"stem":"고개를 푹 숙이고 작은 목소리로 「미안해.」라고 했다면 신나는 마음이에요.","answer":"X","reason_options":[{"t":"고개를 숙이고 작게 말하는 것은 미안한 마음을 보여 주니까","correct":true},{"t":"작은 목소리는 언제나 신난다는 뜻이니까","mis":"K2-1-u5-X02"}],"explanation":["고개를 푹 숙이고 작게 「미안해.」 하면 미안한 마음이에요.","행동이 보여 주는 마음을 거꾸로 읽으면 안 돼요.","행동을 따라 해 보며 마음을 느껴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#4','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],true,'{"seq":4,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"연필","mis":"K2-1-u5-X05"},{"t":"운동장","mis":"K2-1-u5-X05"}],"explanation":["「설레다」는 기대되어 두근거리는 마음을 나타내요.","「연필」은 물건, 「운동장」은 장소예요.","「나는 지금 ○○해.」에 넣어 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 마음을 나타내는 말은 어느 것인가요?","options":[{"t":"뿌듯하다","correct":true},{"t":"의자","mis":"K2-1-u5-X05"},{"t":"달리다","mis":"K2-1-u5-X05"}],"explanation":["「뿌듯하다」는 무언가를 해냈을 때의 마음을 나타내요.","「의자」는 물건, 「달리다」는 움직임이에요.","「나는 지금 ○○해.」에 넣어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#5','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',2,'match','auto','인물의 말이나 행동과 어울리는 마음을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C3","difficulty":2,"kind":"match","stem":"인물의 말이나 행동과 어울리는 마음을 이어 보세요.","pairs":[{"l":"「드디어 됐다!」 하며 두 손을 번쩍 들었어요","r":"기쁘다"},{"l":"고개를 푹 숙이고 「미안해.」 했어요","r":"미안하다"},{"l":"눈을 동그랗게 뜨고 「와, 진짜?」 했어요","r":"놀라다"}],"mis":"K2-1-u5-X02","explanation":["두 손을 번쩍 드는 행동은 기쁜 마음이에요.","고개를 숙이고 「미안해.」 하면 미안한 마음이에요.","눈을 동그랗게 뜨고 「와, 진짜?」 하면 놀란 마음이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 인물의 말이나 행동과 어울리는 마음을 이어 보세요.","pairs":[{"l":"「고마워!」 하며 친구를 꼭 안았어요","r":"고맙다"},{"l":"주먹을 꽉 쥐고 「나 아니야!」 했어요","r":"억울하다"},{"l":"혼자 앉아 창밖만 보았어요","r":"외롭다"}],"explanation":["「고마워!」 하며 안는 행동은 고마운 마음이에요.","「나 아니야!」 하며 주먹을 쥐면 억울한 마음이에요.","혼자 창밖만 보면 외로운 마음일 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#6','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C4',2,'mc','auto','「내일 현장 체험학습을 가요.」 이 상황에 어울리는 마음 말은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],true,'{"seq":6,"concept":"K2-1-u5-C4","difficulty":2,"kind":"mc","stem":"「내일 현장 체험학습을 가요.」 이 상황에 어울리는 마음 말은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"서운하다","mis":"K2-1-u5-X06"},{"t":"미안하다","mis":"K2-1-u5-X06"}],"explanation":["기다리던 일을 앞두면 설레는 마음이 들어요.","서운하거나 미안한 마음은 이 상황과 맞지 않아요.","그 마음이 드는 때를 떠올려 견주어요."],"variant_rule":{"alt":[{"stem":"「친구가 내 부탁을 들어주지 않았어요.」 이 상황에 어울리는 마음 말은 어느 것인가요?","options":[{"t":"서운하다","correct":true},{"t":"설레다","mis":"K2-1-u5-X06"},{"t":"뿌듯하다","mis":"K2-1-u5-X06"}],"explanation":["부탁을 들어주지 않으면 서운한 마음이 들어요.","설레거나 뿌듯한 마음은 이 상황과 맞지 않아요.","그 마음이 드는 때를 떠올려 견주어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#7','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 서준이가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],true,'{"seq":7,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"입술을 삐죽 내밀었어요","correct":true},{"t":"「와, 해냈다!」 하며 손뼉을 쳤어요","mis":"K2-1-u5-X02"},{"t":"비행기가 교실 끝까지 날아갔어요","mis":"K2-1-u5-X08"}],"explanation":["입술을 삐죽 내미는 행동에 속상한 마음이 드러나요.","손뼉을 친 것은 기쁜 마음이 드러난 부분이에요.","비행기가 날아간 것은 일어난 일이지 마음이 드러난 행동이 아니에요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 지우가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"눈물이 핑 돌았어요","correct":true},{"t":"할머니가 활짝 웃으셨어요","mis":"K2-1-u5-X02"},{"t":"할머니 생신 선물로 카드를 만들었어요","mis":"K2-1-u5-X08"}],"explanation":["눈물이 핑 도는 모습에 속상한 마음이 드러나요.","할머니가 웃으신 것은 기쁜 장면이에요.","카드를 만든 것은 일어난 일이에요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#8','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C5',2,'sa','auto','「줄넘기를 처음으로 백 번 넘었어요. 두 팔을 번쩍 들었어요.」 이때의 마음을 나타내는 말을 하나 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C5","difficulty":2,"kind":"sa","stem":"「줄넘기를 처음으로 백 번 넘었어요. 두 팔을 번쩍 들었어요.」 이때의 마음을 나타내는 말을 하나 써 보세요.","answer":["기쁘다","기뻐요","기쁜","뿌듯하다","뿌듯해요","뿌듯한","신나다","신나요","신나는","자랑스럽다","자랑스러워요","자랑스러운"],"explanation":["처음 해낸 일에 두 팔을 번쩍 들었으니 기쁘고 뿌듯한 마음이에요.","「뿌듯하다」·「자랑스럽다」처럼 써도 좋아요.","행동을 보고 마음 말을 골라요."],"variant_rule":{"alt":[{"stem":"「아끼던 인형을 잃어버렸어요. 어깨가 축 처졌어요.」 이때의 마음을 나타내는 말을 하나 써 보세요.","answer":["속상하다","속상해요","속상한","슬프다","슬퍼요","슬픈","아쉽다","아쉬워요","서운하다","서운해요"],"explanation":["아끼던 인형을 잃어버리고 어깨가 처졌으니 속상하고 슬픈 마음이에요.","「슬프다」처럼 써도 좋아요.","상황과 행동을 보고 마음 말을 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#9','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C4',2,'mc','auto','인물의 마음을 더 잘 짐작하려면 어떻게 하면 좋을까요?',ARRAY['K2-1-u5-X01','K2-1-u5-X04']::text[],true,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"mc","stem":"인물의 마음을 더 잘 짐작하려면 어떻게 하면 좋을까요?","options":[{"t":"「나라면 어떤 마음일까?」 비슷한 경험과 견주어 봐요","correct":true},{"t":"인물의 이름만 기억해요","mis":"K2-1-u5-X01"},{"t":"지금 내 기분대로 정해요","mis":"K2-1-u5-X04"}],"explanation":["비슷한 경험을 떠올리면 인물의 마음이 더 생생해져요.","이름만으로는 마음을 알 수 없어요.","지금 내 기분이 아니라 인물의 자리에서 생각해요."],"variant_rule":{"alt":[{"stem":"나도 무언가를 처음 해낸 적이 있다면, 인물의 마음을 짐작할 때 어떻게 하면 좋을까요?","options":[{"t":"그때 내 마음을 떠올려 인물의 마음과 견주어 봐요","correct":true},{"t":"내 경험은 생각하지 않아요","mis":"K2-1-u5-X04"},{"t":"인물의 옷차림을 살펴봐요","mis":"K2-1-u5-X01"}],"explanation":["비슷한 경험을 떠올리면 인물의 마음이 더 잘 느껴져요.","내 경험을 견주면 짐작이 쉬워요.","옷차림은 마음을 알려 주지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_basic#10','kor',2,1,'u5','L03','g2_1_kor_u5_L03_basic','lesson_basic','K2-1-u5-C3',3,'error','auto','글을 읽고 서준이의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C3","difficulty":3,"kind":"error","stem":"글을 읽고 서준이의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"민호 — 「비행기가 교실 끝까지 날아갔을 때 서준이는 속상했을 거야.」","correct":true,"mis_target":"K2-1-u5-X02"},{"t":"소율 — 「바닥에 떨어질 때는 속상했을 거야.」","mis":"K2-1-u5-X17"},{"t":"지후 — 「손뼉을 칠 때는 뿌듯했을 거야.」","mis":"K2-1-u5-X17"}],"explanation":["비행기가 끝까지 날아갔을 때 서준이는 「와, 해냈다!」 하며 기뻐했어요.","속상했던 것은 비행기가 바닥에 떨어질 때예요.","소율이와 지후는 알맞게 짐작했어요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"},"variant_rule":{"alt":[{"stem":"글을 읽고 지우의 마음을 짐작했어요. 잘못 짐작한 친구는 누구인가요?","options":[{"t":"서아 — 「할머니가 활짝 웃으셨을 때 지우는 서운했을 거야.」","correct":true,"mis_target":"K2-1-u5-X02"},{"t":"하준 — 「우유가 쏟아졌을 때는 속상했을 거야.」","mis":"K2-1-u5-X17"},{"t":"아린 — 「마지막에는 마음이 따뜻했을 거야.」","mis":"K2-1-u5-X17"}],"explanation":["할머니가 웃으셨을 때 지우는 마음이 따뜻해졌어요.","서운한 마음은 글에 드러나지 않아요.","하준이와 아린이는 알맞게 짐작했어요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#1','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 할머니가 활짝 웃으셨을 때 지우의 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":1,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 할머니가 활짝 웃으셨을 때 지우의 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"따뜻하고 기쁜 마음","correct":true},{"t":"억울하고 화난 마음","mis":"K2-1-u5-X02"},{"t":"무섭고 떨리는 마음","mis":"K2-1-u5-X08"}],"explanation":["「지우는 마음이 따뜻해졌어요.」라고 했어요.","억울하거나 무서운 마음은 글에 없어요.","글에서 마음이 드러난 부분을 찾아요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#2','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C5',2,'mc','auto','「설레다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":2,"concept":"K2-1-u5-C5","difficulty":2,"kind":"mc","stem":"「설레다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞으로 일어날 일이 기대되어 가슴이 두근거리다","correct":true},{"t":"일이 뜻대로 되지 않아 마음이 상하다","mis":"K2-1-u5-X06"},{"t":"남에게 잘못하여 마음이 편하지 않다","mis":"K2-1-u5-X06"}],"explanation":["소풍 전날처럼 기대될 때 「설레다」를 써요.","마음이 상하는 것은 「속상하다」예요.","잘못해서 마음이 편하지 않은 것은 「미안하다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#3','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',3,'error','auto','상황과 마음을 이었어요. 알맞지 않게 이은 친구는 누구인가요?',ARRAY['K2-1-u5-X03','K2-1-u5-X17']::text[],false,'{"seq":3,"concept":"K2-1-u5-C4","difficulty":3,"kind":"error","stem":"상황과 마음을 이었어요. 알맞지 않게 이은 친구는 누구인가요?","options":[{"t":"태민 — 「친구가 약속을 잊어버렸어요 → 뿌듯하다」","correct":true,"mis_target":"K2-1-u5-X03"},{"t":"은솔 — 「오랫동안 기다린 일이 이루어졌어요 → 기쁘다」","mis":"K2-1-u5-X17"},{"t":"아린 — 「내일 좋아하는 곳에 가요 → 설레다」","mis":"K2-1-u5-X17"}],"explanation":["친구가 약속을 잊으면 서운한 마음이 들어요.","「뿌듯하다」는 무언가를 해냈을 때의 마음이에요.","은솔이와 아린이는 알맞게 이었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#4','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C3',3,'mc','auto','「괜찮아.」라고 말하면서 손으로 눈물을 훔쳤어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":4,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「괜찮아.」라고 말하면서 손으로 눈물을 훔쳤어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 괜찮다고 했지만 사실은 속상한 마음","correct":true},{"t":"말 그대로 정말 괜찮고 기쁜 마음","mis":"K2-1-u5-X02"},{"t":"졸리고 심심한 마음","mis":"K2-1-u5-X03"}],"explanation":["눈물을 훔치는 행동에서 속상한 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","졸리거나 심심한 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#5','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',3,'ox','auto','같은 일이 생겨도 사람마다 마음이 다를 수 있어요.',ARRAY['K2-1-u5-X04']::text[],false,'{"seq":5,"concept":"K2-1-u5-C4","difficulty":3,"kind":"ox","stem":"같은 일이 생겨도 사람마다 마음이 다를 수 있어요.","answer":"O","reason_options":[{"t":"겪은 일과 처지가 달라 느끼는 마음도 다를 수 있으니까","correct":true},{"t":"같은 일이면 누구나 똑같은 마음이니까","mis":"K2-1-u5-X04"}],"mis":"K2-1-u5-X04","explanation":["블록 탑이 무너지면 언니는 속상하고 동생은 미안할 수 있어요.","사람마다 처지가 달라요.","그래서 인물마다 나누어 마음을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#6','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C5',3,'mc','auto','서로 비슷한 마음을 나타내는 말끼리 모은 것은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":6,"concept":"K2-1-u5-C5","difficulty":3,"kind":"mc","stem":"서로 비슷한 마음을 나타내는 말끼리 모은 것은 어느 것인가요?","options":[{"t":"기쁘다 · 즐겁다 · 신나다","correct":true},{"t":"기쁘다 · 속상하다 · 신나다","mis":"K2-1-u5-X06"},{"t":"슬프다 · 설레다 · 뿌듯하다","mis":"K2-1-u5-X06"}],"explanation":["「기쁘다」·「즐겁다」·「신나다」는 모두 좋은 일이 있을 때의 마음이에요.","「속상하다」·「슬프다」는 마음이 상할 때의 말이에요.","마음 말이 드는 때를 떠올려 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#7','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C3',3,'mc','auto','글을 읽고 답해 보세요. 서준이가 날개를 다시 반듯이 접어 힘껏 날린 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X08']::text[],false,'{"seq":7,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이가 날개를 다시 반듯이 접어 힘껏 날린 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"포기하지 않고 다시 해 보고 싶어서","correct":true},{"t":"종이비행기가 싫어져서","mis":"K2-1-u5-X08"},{"t":"친구가 시켜서","mis":"K2-1-u5-X08"}],"explanation":["비행기가 자꾸 떨어져도 다시 접어 날렸어요.","종이비행기가 싫었다면 다시 접지 않았을 거예요.","친구가 시켰다는 말은 글에 없어요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#8','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',4,'mc','auto','하윤이는 발표를 앞두고 손에 땀이 나고 목소리가 작아졌어요. 하윤이의 마음과 해 줄 말을 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":8,"concept":"K2-1-u5-C4","difficulty":4,"kind":"mc","stem":"하윤이는 발표를 앞두고 손에 땀이 나고 목소리가 작아졌어요. 하윤이의 마음과 해 줄 말을 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"떨리는 마음 — 「천천히 해도 괜찮아.」","correct":true},{"t":"신나는 마음 — 「더 크게 소리 질러!」","mis":"K2-1-u5-X02"},{"t":"화난 마음 — 「왜 화가 났어?」","mis":"K2-1-u5-X03"}],"explanation":["손에 땀이 나고 목소리가 작아지는 것은 떨리는 마음이에요.","떨리는 친구에게는 마음을 놓게 해 주는 말이 어울려요.","상황과 행동을 함께 살펴 마음을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#9','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C3',4,'essay','teacher','「종이비행기」에서 서준이의 마음을 두 가지 찾아 쓰고, 각각 어떤 말이나 행동을 보고 짐작했는지 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C3","difficulty":4,"kind":"essay","stem":"「종이비행기」에서 서준이의 마음을 두 가지 찾아 쓰고, 각각 어떤 말이나 행동을 보고 짐작했는지 써 보세요.","answer_guide":{"answer":"예: 속상한 마음 — 비행기가 떨어지자 입술을 삐죽 내밀었어요. 뿌듯한 마음 — 「와, 해냈다!」 하며 손뼉을 쳤어요.","scoring_points":["서준이의 마음을 두 가지 썼는가","마음마다 근거가 된 말이나 행동을 글에서 찾아 썼는가","마음을 마음 말로 알맞게 나타냈는가"]},"explanation":["마음 두 가지.","근거가 된 말·행동.","마음 말."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L03_challenge#10','kor',2,1,'u5','L03','g2_1_kor_u5_L03_challenge','lesson_challenge','K2-1-u5-C4',4,'essay','teacher','무언가를 처음 해낸 경험을 떠올려 그때 내 마음을 마음 말로 쓰고, 서준이의 마음과 견주어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C4","difficulty":4,"kind":"essay","stem":"무언가를 처음 해낸 경험을 떠올려 그때 내 마음을 마음 말로 쓰고, 서준이의 마음과 견주어 써 보세요.","answer_guide":{"answer":"예: 처음으로 혼자 머리를 묶었을 때 정말 뿌듯했어요. 서준이도 비행기가 끝까지 날아갔을 때 나처럼 뿌듯했을 거예요.","scoring_points":["처음 해낸 경험을 썼는가","그때의 마음을 마음 말로 썼는가","서준이의 마음과 견주어 썼는가"]},"explanation":["나의 경험.","마음 말.","서준이와 견주기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#1','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'mc','auto','글을 읽고 답해 보세요. 처음 수영장 물을 보았을 때 지안이의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X02']::text[],true,'{"seq":1,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 처음 수영장 물을 보았을 때 지안이의 마음은 어느 것인가요?","options":[{"t":"무섭고 걱정되는 마음","correct":true},{"t":"신나고 들뜬 마음","mis":"K2-1-u5-X07"},{"t":"화나고 억울한 마음","mis":"K2-1-u5-X02"}],"explanation":["엄마 손을 꼭 잡고 「물이 너무 깊어 보여…….」라고 했어요.","신나는 마음은 나중에 물장구를 칠 때의 마음이에요.","장면마다 마음을 나누어 짐작해요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 무대 뒤에서 다리가 후들후들 떨릴 때 아기 곰의 마음은 어느 것인가요?","options":[{"t":"떨리고 걱정되는 마음","correct":true},{"t":"뿌듯하고 자랑스러운 마음","mis":"K2-1-u5-X07"},{"t":"졸리고 심심한 마음","mis":"K2-1-u5-X03"}],"explanation":["다리가 후들후들 떨리는 모습에서 떨리고 걱정되는 마음이 드러나요.","뿌듯한 마음은 나중에 북을 다 친 뒤의 마음이에요.","장면마다 마음을 나누어 짐작해요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#2','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'mc','auto','글을 읽고 답해 보세요. 첨벙첨벙 물장구를 치며 깔깔 웃을 때 지안이의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X02']::text[],true,'{"seq":2,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 첨벙첨벙 물장구를 치며 깔깔 웃을 때 지안이의 마음은 어느 것인가요?","options":[{"t":"즐겁고 신나는 마음","correct":true},{"t":"무섭고 걱정되는 마음","mis":"K2-1-u5-X07"},{"t":"서운하고 슬픈 마음","mis":"K2-1-u5-X02"}],"explanation":["깔깔 웃으며 물장구를 치는 모습에서 즐거운 마음이 드러나요.","무서운 마음은 처음 물을 보았을 때의 마음이에요.","마음은 시간이 지나며 바뀔 수 있어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 가슴을 쭉 펴고 환하게 웃을 때 아기 곰의 마음은 어느 것인가요?","options":[{"t":"뿌듯하고 기쁜 마음","correct":true},{"t":"떨리고 걱정되는 마음","mis":"K2-1-u5-X07"},{"t":"미안하고 부끄러운 마음","mis":"K2-1-u5-X02"}],"explanation":["가슴을 쭉 펴고 환하게 웃는 모습에서 뿌듯한 마음이 드러나요.","떨리는 마음은 무대 뒤에 있을 때의 마음이에요.","마음은 시간이 지나며 바뀔 수 있어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#3','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'ox','auto','글 속 인물의 마음은 처음부터 끝까지 늘 똑같아요.',ARRAY['K2-1-u5-X07']::text[],true,'{"seq":3,"concept":"K2-1-u5-C6","difficulty":1,"kind":"ox","stem":"글 속 인물의 마음은 처음부터 끝까지 늘 똑같아요.","answer":"X","reason_options":[{"t":"일이 일어나면 인물의 마음이 바뀔 수 있으니까","correct":true},{"t":"한 번 든 마음은 바뀌지 않으니까","mis":"K2-1-u5-X07"}],"mis":"K2-1-u5-X07","explanation":["지안이는 처음에 무서웠지만 나중에는 즐거워졌어요.","일이 일어난 차례에 따라 마음이 바뀌어요.","장면마다 마음을 짐작해요."],"variant_rule":{"alt":[{"stem":"시간이 지나며 일어난 일에 따라 인물의 마음이 바뀔 수 있어요.","answer":"O","reason_options":[{"t":"친구가 다가와 주는 것 같은 일이 마음을 바꾸니까","correct":true},{"t":"인물의 마음은 처음 그대로이니까","mis":"K2-1-u5-X07"}],"explanation":["친구의 응원이나 도움 같은 일이 마음을 바꾸어요.","그래서 장면마다 마음을 살펴요.","처음 → 무슨 일 → 나중을 따라가요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#4','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',1,'mc','auto','글을 읽고 답해 보세요. 지안이의 마음을 바꾸어 준 일은 무엇인가요?',ARRAY['K2-1-u5-X08']::text[],true,'{"seq":4,"concept":"K2-1-u5-C6","difficulty":1,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이의 마음을 바꾸어 준 일은 무엇인가요?","options":[{"t":"하람이가 같이 손잡고 들어가자고 한 일","correct":true},{"t":"엄마가 먼저 집에 간 일","mis":"K2-1-u5-X08"},{"t":"비가 내려 수영장이 문을 닫은 일","mis":"K2-1-u5-X08"}],"explanation":["하람이가 「같이 손잡고 들어가자!」 하고 웃은 뒤 지안이는 물에 발을 담갔어요.","엄마가 집에 갔다거나 비가 왔다는 말은 글에 없어요.","마음이 바뀐 까닭을 글에서 찾아요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 아기 곰의 마음을 바꾸어 준 일은 무엇인가요?","options":[{"t":"다람쥐가 어깨를 토닥이며 응원한 일","correct":true},{"t":"음악회가 취소된 일","mis":"K2-1-u5-X08"},{"t":"북이 부서진 일","mis":"K2-1-u5-X08"}],"explanation":["다람쥐가 「넌 잘할 수 있어!」 하고 토닥인 뒤 아기 곰은 북을 쳤어요.","음악회가 취소되거나 북이 부서졌다는 말은 글에 없어요.","마음이 바뀐 까닭을 글에서 찾아요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#5','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',2,'match','auto','글을 읽고 장면과 그때 지안이의 마음을 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C6","difficulty":2,"kind":"match","stem":"글을 읽고 장면과 그때 지안이의 마음을 이어 보세요.","pairs":[{"l":"엄마 손을 꼭 잡았을 때","r":"무섭다"},{"l":"조심조심 발을 담갔을 때","r":"용기를 내다"},{"l":"물장구를 치며 깔깔 웃을 때","r":"신나다"}],"mis":"K2-1-u5-X07","explanation":["물을 처음 볼 때는 무서웠어요.","하람이 말을 듣고 용기를 내어 발을 담갔어요.","물장구를 칠 때는 신났어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 장면과 그때 아기 곰의 마음을 이어 보세요.","pairs":[{"l":"다리가 후들후들 떨릴 때","r":"떨리다"},{"l":"「넌 잘할 수 있어!」를 들었을 때","r":"고맙다"},{"l":"친구들이 손뼉을 칠 때","r":"뿌듯하다"}],"explanation":["무대 뒤에서는 떨렸어요.","다람쥐의 응원에 고마웠어요.","친구들의 손뼉에 뿌듯했어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#6','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 지안이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],true,'{"seq":6,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"무섭다 → 용기를 내다 → 신나다","correct":true},{"t":"신나다 → 무섭다 → 용기를 내다","mis":"K2-1-u5-X07"},{"t":"무섭다 → 무섭다 → 무섭다","mis":"K2-1-u5-X07"}],"explanation":["처음에는 무서웠고, 하람이 말에 용기를 내었고, 나중에는 신났어요.","차례를 뒤바꾸면 이야기가 달라져요.","마음은 처음 그대로 있지 않았어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 아기 곰의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"떨리다 → 힘이 나다 → 뿌듯하다","correct":true},{"t":"뿌듯하다 → 떨리다 → 힘이 나다","mis":"K2-1-u5-X07"},{"t":"떨리다 → 떨리다 → 떨리다","mis":"K2-1-u5-X07"}],"explanation":["처음에는 떨렸고, 다람쥐 응원에 힘이 났고, 나중에는 뿌듯했어요.","차례를 뒤바꾸면 이야기가 달라져요.","마음은 처음 그대로 있지 않았어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#7','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C9',2,'mc','auto','글을 읽고 답해 보세요. 「물이 너무 깊어 보여…….」를 지안이의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u5-X15']::text[],true,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 「물이 너무 깊어 보여…….」를 지안이의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?","options":[{"t":"작고 걱정스러운 목소리로","correct":true},{"t":"크고 신나는 목소리로","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["지안이는 물이 무서워 걱정하고 있어요.","크고 신나게 읽으면 걱정하는 마음이 드러나지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 「넌 잘할 수 있어!」를 다람쥐의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?","options":[{"t":"다정하고 힘을 주는 목소리로","correct":true},{"t":"졸린 듯 작은 목소리로","mis":"K2-1-u5-X15"},{"t":"놀리는 듯한 목소리로","mis":"K2-1-u5-X15"}],"explanation":["다람쥐는 아기 곰을 응원하고 있어요.","졸리거나 놀리는 목소리는 응원하는 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#8','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',2,'sa','auto','글을 읽고 답해 보세요. 지안이에게 「같이 손잡고 들어가자!」 하고 말한 친구의 이름을 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C6","difficulty":2,"kind":"sa","stem":"글을 읽고 답해 보세요. 지안이에게 「같이 손잡고 들어가자!」 하고 말한 친구의 이름을 써 보세요.","answer":["하람","하람이"],"explanation":["「그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.」라고 했어요.","하람이의 말이 지안이의 마음을 바꾸었어요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 답해 보세요. 아기 곰에게 「넌 잘할 수 있어!」 하고 말한 동물을 써 보세요.","answer":["다람쥐"],"explanation":["「다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.」라고 했어요.","다람쥐의 말이 아기 곰의 마음을 바꾸었어요.","글에서 찾아 짚어 봐요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#9','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',2,'mc','auto','인물의 마음이 어떻게 바뀌었는지 알려면 무엇을 살펴보면 좋을까요?',ARRAY['K2-1-u5-X01','K2-1-u5-X07']::text[],true,'{"seq":9,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"인물의 마음이 어떻게 바뀌었는지 알려면 무엇을 살펴보면 좋을까요?","options":[{"t":"일이 일어난 차례와 장면마다 인물의 말과 행동","correct":true},{"t":"글의 제목 글자 수","mis":"K2-1-u5-X01"},{"t":"글의 마지막 문장 하나만","mis":"K2-1-u5-X07"}],"explanation":["일이 일어난 차례를 따라가며 장면마다 마음을 짐작해요.","글자 수는 마음과 상관없어요.","마지막 문장만 보면 처음 마음을 놓쳐요."],"variant_rule":{"alt":[{"stem":"인물의 마음 변화를 정리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"「처음 → 무슨 일 → 나중」 차례로 마음을 적어요","correct":true},{"t":"마지막 마음 하나만 적어요","mis":"K2-1-u5-X07"},{"t":"인물의 이름만 적어요","mis":"K2-1-u5-X01"}],"explanation":["처음 마음, 마음을 바꾼 일, 나중 마음을 차례로 적어요.","마지막 마음만 적으면 변화가 보이지 않아요.","이름만으로는 마음을 알 수 없어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_basic#10','kor',2,1,'u5','L05','g2_1_kor_u5_L05_basic','lesson_basic','K2-1-u5-C6',3,'error','auto','글을 읽고 지안이의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 지안이의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「지안이는 처음부터 수영장이 하나도 무섭지 않았어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"예린 — 「처음에는 엄마 손을 꼭 잡을 만큼 무서웠어.」","mis":"K2-1-u5-X17"},{"t":"현우 — 「나중에는 물장구를 치며 신났어.」","mis":"K2-1-u5-X17"}],"explanation":["지안이는 처음에 물이 깊어 보여 무서워했어요.","마음이 처음부터 그대로였던 것이 아니에요.","예린이와 현우는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"},"variant_rule":{"alt":[{"stem":"글을 읽고 아기 곰의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"지우 — 「아기 곰은 처음부터 하나도 떨리지 않았어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"도담 — 「무대 뒤에서는 다리가 떨렸어.」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「나중에는 가슴을 펴고 웃었어.」","mis":"K2-1-u5-X17"}],"explanation":["아기 곰은 무대 뒤에서 다리가 후들후들 떨렸어요.","마음이 처음부터 그대로였던 것이 아니에요.","도담이와 서윤이는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#1','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 동생이 카드에 우유를 쏟았을 때 지우의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":1,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 동생이 카드에 우유를 쏟았을 때 지우의 마음은 어느 것인가요?","options":[{"t":"속상한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u5-X02"},{"t":"고마운 마음","mis":"K2-1-u5-X02"}],"explanation":["정성껏 만든 카드가 젖어 눈물이 핑 돌았어요.","신나거나 고마운 마음은 이 장면과 맞지 않아요.","장면마다 마음을 짐작해요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#2','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 아기 곰이 가슴을 쭉 펼 수 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X08','K2-1-u5-X07']::text[],false,'{"seq":2,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 아기 곰이 가슴을 쭉 펼 수 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"다람쥐의 응원을 받고 북을 끝까지 쳐서 친구들이 손뼉을 쳐 주었으니까","correct":true},{"t":"무대에 오르지 않고 집에 갔으니까","mis":"K2-1-u5-X08"},{"t":"처음부터 하나도 떨리지 않았으니까","mis":"K2-1-u5-X07"}],"explanation":["응원을 받고 북을 쳤더니 친구들이 손뼉을 쳤어요.","집에 갔다는 말은 글에 없어요.","아기 곰은 처음에 떨렸어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#3','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',3,'mc','auto','글을 읽고 답해 보세요. 우유가 쏟아진 뒤부터 지우의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":3,"concept":"K2-1-u5-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 우유가 쏟아진 뒤부터 지우의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하다 → 따뜻하다","correct":true},{"t":"따뜻하다 → 속상하다","mis":"K2-1-u5-X07"},{"t":"속상하다 → 속상하다","mis":"K2-1-u5-X07"}],"explanation":["우유가 쏟아져 속상했다가, 할머니가 웃으셔서 마음이 따뜻해졌어요.","차례를 뒤바꾸면 이야기가 달라져요.","마음은 처음 그대로 있지 않았어요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#4','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',3,'error','auto','글을 읽고 아기 곰의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X08','K2-1-u5-X17']::text[],false,'{"seq":4,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 아기 곰의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"하람 — 「친구들이 손뼉을 칠 때 아기 곰은 부끄러워서 숨고 싶었어.」","correct":true,"mis_target":"K2-1-u5-X08"},{"t":"지호 — 「무대 뒤에서는 떨렸어.」","mis":"K2-1-u5-X17"},{"t":"민지 — 「다람쥐 덕분에 힘이 났어.」","mis":"K2-1-u5-X17"}],"explanation":["아기 곰은 손뼉 소리에 가슴을 펴고 환하게 웃었어요.","숨고 싶었다는 말은 글에 없어요.","지호와 민지는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#5','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C3',3,'ox','auto','글을 읽고 답해 보세요. 우유를 쏟은 동생은 미안한 마음이었어요.',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":5,"concept":"K2-1-u5-C3","difficulty":3,"kind":"ox","stem":"글을 읽고 답해 보세요. 우유를 쏟은 동생은 미안한 마음이었어요.","answer":"O","reason_options":[{"t":"고개를 숙이고 「언니, 미안해.」라고 했으니까","correct":true},{"t":"장난을 쳐서 신났으니까","mis":"K2-1-u5-X02"}],"mis":"K2-1-u5-X02","explanation":["고개를 숙이고 「미안해.」라고 한 말과 행동에서 미안한 마음이 드러나요.","장난을 쳤다는 말은 글에 없어요.","말과 행동을 함께 살펴요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#6','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C9',3,'mc','auto','「친구들과 함께 깔깔 웃으며 노는 장면」을 인물의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":6,"concept":"K2-1-u5-C9","difficulty":3,"kind":"mc","stem":"「친구들과 함께 깔깔 웃으며 노는 장면」을 인물의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?","options":[{"t":"밝고 즐거운 목소리로","correct":true},{"t":"작고 울먹이는 목소리로","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["함께 웃으며 노는 장면은 즐거운 마음이에요.","울먹이거나 화난 목소리는 즐거운 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#7','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',3,'mc','auto','글을 읽고 답해 보세요. 지안이가 조심조심 물에 발을 담글 때의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X03']::text[],false,'{"seq":7,"concept":"K2-1-u5-C6","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이가 조심조심 물에 발을 담글 때의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"아직 조금 무섭지만 용기를 내 보는 마음","correct":true},{"t":"물이 하나도 무섭지 않은 마음","mis":"K2-1-u5-X07"},{"t":"엄마에게 화가 난 마음","mis":"K2-1-u5-X03"}],"explanation":["「조심조심」에서 아직 조금 무서운 마음이, 발을 담그는 행동에서 용기가 보여요.","하나도 무섭지 않았다면 조심조심하지 않았을 거예요.","화가 났다는 단서는 글에 없어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#8','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',4,'mc','auto','인물의 마음 변화를 따라가며 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":8,"concept":"K2-1-u5-C6","difficulty":4,"kind":"mc","stem":"인물의 마음 변화를 따라가며 읽으면 좋은 점으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"무슨 일 때문에 마음이 바뀌었는지 알게 되어 글이 더 잘 이해돼요","correct":true},{"t":"마지막 마음만 알면 되어 빨리 읽을 수 있어요","mis":"K2-1-u5-X07"},{"t":"인물의 처음 마음만 기억하면 돼요","mis":"K2-1-u5-X07"}],"explanation":["마음이 바뀐 까닭을 알면 이야기가 더 잘 보여요.","마지막 마음만 보면 변화를 놓쳐요.","처음 마음만 기억해도 변화를 알 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#9','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',4,'essay','teacher','「숲속 음악회」에서 아기 곰의 마음이 처음·가운데·끝에 어떠했는지 쓰고, 마음이 바뀐 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"「숲속 음악회」에서 아기 곰의 마음이 처음·가운데·끝에 어떠했는지 쓰고, 마음이 바뀐 까닭을 써 보세요.","answer_guide":{"answer":"예: 처음에는 다리가 떨려 걱정되었어요. 다람쥐가 응원해 주어 힘이 났어요. 끝에는 친구들이 손뼉을 쳐 주어 뿌듯했어요. 다람쥐의 응원과 친구들의 손뼉 때문에 마음이 바뀌었어요.","scoring_points":["처음·가운데·끝의 마음을 차례대로 썼는가","마음을 마음 말로 알맞게 나타냈는가","마음이 바뀐 까닭을 글에서 찾아 썼는가"]},"explanation":["세 장면의 마음.","마음 말.","바뀐 까닭."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L05_challenge#10','kor',2,1,'u5','L05','g2_1_kor_u5_L05_challenge','lesson_challenge','K2-1-u5-C6',4,'essay','teacher','처음 마음과 나중 마음이 달랐던 내 경험을 「처음에는 ~했는데, ~ 때문에 ~해졌어요.」의 꼴로 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"처음 마음과 나중 마음이 달랐던 내 경험을 「처음에는 ~했는데, ~ 때문에 ~해졌어요.」의 꼴로 써 보세요.","answer_guide":{"answer":"예: 처음에는 새 반이 낯설어 떨렸는데, 짝이 먼저 말을 걸어 주어 편안해졌어요.","scoring_points":["처음 마음을 썼는가","마음을 바꾼 일을 썼는가","나중 마음을 마음 말로 썼는가"]},"explanation":["처음 마음.","마음을 바꾼 일.","나중 마음."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#1','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',1,'blank','auto','「텃밭의 상추가 잘 자라도록 (     )을 주었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":1,"concept":"K2-1-u5-C7","difficulty":1,"kind":"blank","stem":"「텃밭의 상추가 잘 자라도록 (     )을 주었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"거름","correct":true},{"t":"걸음","mis":"K2-1-u5-X09"},{"t":"거럼","mis":"K2-1-u5-X09"}],"explanation":["식물을 잘 자라게 하려고 흙에 주는 것은 「거름」이에요.","「걸음」은 발을 옮겨 걷는 것이에요.","소리가 같아도 문장의 뜻을 보고 골라요."],"variant_rule":{"alt":[{"stem":"「아기가 한 (     )씩 천천히 걸었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"걸음","correct":true},{"t":"거름","mis":"K2-1-u5-X09"},{"t":"걸름","mis":"K2-1-u5-X09"}],"explanation":["발을 옮겨 걷는 것은 「걸음」이에요.","「거름」은 식물을 잘 자라게 하는 흙이에요.","소리가 같아도 문장의 뜻을 보고 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#2','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',1,'mc','auto','「다치다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":2,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「다치다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸에 상처를 입다","correct":true},{"t":"열려 있던 것이 막히다","mis":"K2-1-u5-X09"},{"t":"하던 일을 끝내다","mis":"K2-1-u5-X09"}],"explanation":["「무릎을 다치다」처럼 몸에 상처를 입는 것이 「다치다」예요.","열려 있던 것이 막히는 것은 「닫히다」예요.","일을 끝내는 것은 「마치다」예요."],"variant_rule":{"alt":[{"stem":"「닫히다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"열려 있던 것이 막히다","correct":true},{"t":"몸에 상처를 입다","mis":"K2-1-u5-X09"},{"t":"목표에 닿게 하다","mis":"K2-1-u5-X09"}],"explanation":["「문이 닫히다」처럼 열려 있던 것이 막히는 것이 「닫히다」예요.","몸에 상처를 입는 것은 「다치다」예요.","목표에 닿게 하는 것은 「맞히다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#3','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',1,'ox','auto','「종이 울려서 수업을 맞혔어요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":3,"concept":"K2-1-u5-C7","difficulty":1,"kind":"ox","stem":"「종이 울려서 수업을 맞혔어요.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"하던 일을 끝내는 것은 「마치다」라서 「마쳤어요」라고 써야 하니까","correct":true},{"t":"소리가 같으면 아무 낱말이나 써도 되니까","mis":"K2-1-u5-X09"}],"mis":"K2-1-u5-X09","explanation":["수업을 끝내는 것은 「마치다」예요.","「맞히다」는 과녁이나 답을 맞게 하는 거예요.","소리가 같아도 뜻을 보고 골라요."],"variant_rule":{"alt":[{"stem":"「공을 던져 과녁을 맞혔어요.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"목표에 닿게 하는 것은 「맞히다」니까","correct":true},{"t":"소리가 같으면 「마쳤어요」라고 써도 되니까","mis":"K2-1-u5-X09"}],"explanation":["과녁에 닿게 하는 것은 「맞히다」예요.","「마치다」는 하던 일을 끝내는 거예요.","소리가 같아도 뜻을 보고 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#4','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',1,'mc','auto','바르게 쓴 문장은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":4,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「넘어져서 무릎을 다쳤어요.」","correct":true},{"t":"「넘어져서 무릎을 닫혔어요.」","mis":"K2-1-u5-X09"},{"t":"「넘어져서 무릎을 맞혔어요.」","mis":"K2-1-u5-X09"}],"explanation":["몸에 상처를 입는 것은 「다치다」예요.","「닫히다」는 문 같은 것이 막히는 거예요.","「맞히다」는 목표에 닿게 하는 거예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「바람이 불어서 문이 닫혔어요.」","correct":true},{"t":"「바람이 불어서 문이 다쳤어요.」","mis":"K2-1-u5-X09"},{"t":"「바람이 불어서 문이 마쳤어요.」","mis":"K2-1-u5-X09"}],"explanation":["열려 있던 문이 막히는 것은 「닫히다」예요.","「다치다」는 몸에 상처를 입는 거예요.","「마치다」는 하던 일을 끝내는 거예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#5','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'match','auto','낱말과 뜻을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"가르치다","r":"모르는 것을 알려 주다"},{"l":"가리키다","r":"손가락으로 방향이나 물건을 짚어 보이다"},{"l":"반드시","r":"틀림없이 꼭"}],"mis":"K2-1-u5-X10","explanation":["「한글을 가르치다」처럼 알려 주는 것이 「가르치다」예요.","「손가락으로 가리키다」처럼 짚어 보이는 것이 「가리키다」예요.","「반드시」는 틀림없이 꼭이라는 뜻이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"잊다","r":"알던 것을 기억하지 못하다"},{"l":"잃다","r":"가졌던 물건이 없어지다"},{"l":"바라다","r":"어떤 일이 이루어지기를 원하다"}],"explanation":["「약속을 잊다」처럼 기억하지 못하는 것이 「잊다」예요.","「장갑을 잃다」처럼 물건이 없어지는 것이 「잃다」예요.","「소원이 이루어지기를 바라다」처럼 원하는 것이 「바라다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#6','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'blank','auto','「선생님께서 우리에게 한글을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],true,'{"seq":6,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「선생님께서 우리에게 한글을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"가르쳐 주셨어요","correct":true},{"t":"가리켜 주셨어요","mis":"K2-1-u5-X10"},{"t":"가르켜 주셨어요","mis":"K2-1-u5-X09"}],"explanation":["모르는 것을 알려 주는 것은 「가르치다」예요.","「가리키다」는 손가락으로 짚어 보이는 거예요.","「가르켜」는 없는 말이에요."],"variant_rule":{"alt":[{"stem":"「동생이 손가락으로 하늘의 무지개를 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"가리켰어요","correct":true},{"t":"가르쳤어요","mis":"K2-1-u5-X10"},{"t":"가르켰어요","mis":"K2-1-u5-X09"}],"explanation":["손가락으로 짚어 보이는 것은 「가리키다」예요.","「가르치다」는 모르는 것을 알려 주는 거예요.","「가르켰어요」는 없는 말이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#7','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'mc','auto','「다르다」를 바르게 쓴 문장은 어느 것인가요?',ARRAY['K2-1-u5-X10']::text[],true,'{"seq":7,"concept":"K2-1-u5-C7","difficulty":2,"kind":"mc","stem":"「다르다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「나와 동생은 좋아하는 과일이 달라요.」","correct":true},{"t":"「나와 동생은 좋아하는 과일이 틀려요.」","mis":"K2-1-u5-X10"},{"t":"「쌍둥이지만 키가 조금 틀려요.」","mis":"K2-1-u5-X10"}],"explanation":["같지 않은 것은 「다르다」예요.","「틀리다」는 맞지 않을 때 써요.","쌍둥이의 키가 같지 않은 것도 「다르다」로 써요."],"variant_rule":{"alt":[{"stem":"「틀리다」를 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"「셈을 잘못해서 답이 틀렸어요.」","correct":true},{"t":"「쌍둥이지만 얼굴이 조금 틀려요.」","mis":"K2-1-u5-X10"},{"t":"「내 신발과 네 신발은 크기가 틀려요.」","mis":"K2-1-u5-X10"}],"explanation":["맞지 않은 것은 「틀리다」예요.","얼굴이나 크기가 같지 않은 것은 「다르다」예요.","「다르다」와 「틀리다」는 뜻이 서로 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#8','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'sa','auto','「어떤 일이 이루어지기를 원하다」라는 뜻의 낱말을 「바라다」와 「바래다」 가운데 골라 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C7","difficulty":2,"kind":"sa","stem":"「어떤 일이 이루어지기를 원하다」라는 뜻의 낱말을 「바라다」와 「바래다」 가운데 골라 써 보세요.","answer":["바라다"],"explanation":["「소원이 이루어지기를 바라다」처럼 원하는 것은 「바라다」예요.","「바래다」는 색이 옅어지는 거예요.","그래서 「꼭 이기기를 바라요.」라고 써요."],"variant_rule":{"alt":[{"stem":"「가졌던 물건이 없어지다」라는 뜻의 낱말을 「잊다」와 「잃다」 가운데 골라 써 보세요.","answer":["잃다"],"explanation":["「장갑을 잃다」처럼 물건이 없어지는 것은 「잃다」예요.","「잊다」는 알던 것을 기억하지 못하는 거예요.","뜻을 말로 풀어 보고 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#9','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',2,'mc','auto','헷갈리기 쉬운 낱말을 바르게 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],true,'{"seq":9,"concept":"K2-1-u5-C7","difficulty":2,"kind":"mc","stem":"헷갈리기 쉬운 낱말을 바르게 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"문장의 뜻을 생각하며 알맞은 낱말을 골라요","correct":true},{"t":"소리 나는 대로 아무 낱말이나 골라요","mis":"K2-1-u5-X09"},{"t":"글자 수가 더 많은 낱말을 골라요","mis":"K2-1-u5-X09"}],"explanation":["문장의 뜻을 생각해야 알맞은 낱말을 고를 수 있어요.","소리가 같아도 뜻이 다른 낱말이 있어요.","글자 수는 뜻과 상관없어요."],"variant_rule":{"alt":[{"stem":"헷갈리기 쉬운 낱말을 잘못 쓰면 어떻게 될까요?","options":[{"t":"전하고 싶은 뜻이 잘못 전해져요","correct":true},{"t":"뜻은 언제나 똑같이 전해져요","mis":"K2-1-u5-X09"},{"t":"글이 더 재미있어져요","mis":"K2-1-u5-X09"}],"explanation":["「걸음」을 「거름」으로 쓰면 뜻이 달라져요.","소리가 같아도 뜻이 같지 않아요.","그래서 뜻을 생각하며 골라 써요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_basic#10','kor',2,1,'u5','L07','g2_1_kor_u5_L07_basic','lesson_basic','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X09','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"하준 — 「반듯이 숙제를 하고 놀 거예요.」","correct":true,"mis_target":"K2-1-u5-X09"},{"t":"예린 — 「의자에 반듯이 앉았어요.」","mis":"K2-1-u5-X17"},{"t":"소율 — 「숙제를 마치고 놀았어요.」","mis":"K2-1-u5-X17"}],"explanation":["「꼭」이라는 뜻은 「반드시」라고 써야 해요.","「반듯이」는 곧고 바르게라는 뜻이에요.","예린이와 소율이는 뜻에 맞게 바르게 썼어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호 — 「놀이터에서 장갑을 잊어버렸어요.」","correct":true,"mis_target":"K2-1-u5-X10"},{"t":"다은 — 「친구 생일을 잊지 않았어요.」","mis":"K2-1-u5-X17"},{"t":"시우 — 「공원에서 모자를 잃어버렸어요.」","mis":"K2-1-u5-X17"}],"explanation":["물건이 없어진 것은 「잃어버렸어요」라고 써야 해요.","「잊다」는 알던 것을 기억하지 못하는 거예요.","다은이와 시우는 뜻에 맞게 바르게 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#1','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',2,'mc','auto','「반듯이」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":1,"concept":"K2-1-u5-C7","difficulty":2,"kind":"mc","stem":"「반듯이」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"비뚤어지지 않고 곧고 바르게","correct":true},{"t":"틀림없이 꼭","mis":"K2-1-u5-X09"},{"t":"아주 빠르게","mis":"K2-1-u5-X09"}],"explanation":["「반듯이 앉다」처럼 곧고 바르게라는 뜻이에요.","「틀림없이 꼭」은 「반드시」의 뜻이에요.","소리가 같아도 뜻이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#2','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',2,'blank','auto','「오래 입은 티셔츠의 색이 누렇게 (     ).」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],false,'{"seq":2,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「오래 입은 티셔츠의 색이 누렇게 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"바랬어요","correct":true},{"t":"바랐어요","mis":"K2-1-u5-X10"},{"t":"바렜어요","mis":"K2-1-u5-X09"}],"explanation":["색이 옅어지는 것은 「바래다」라서 「바랬어요」예요.","「바랐어요」는 원했다는 뜻이에요.","「바렜어요」는 없는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#3','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'error','auto','일기 한 줄씩을 읽었어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X09','K2-1-u5-X17']::text[],false,'{"seq":3,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"일기 한 줄씩을 읽었어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"태민 — 「계단에서 넘어져 무릎을 닫혀서 약을 발랐다.」","correct":true,"mis_target":"K2-1-u5-X09"},{"t":"은솔 — 「선생님께서 칠판의 글자를 가리키셨다.」","mis":"K2-1-u5-X17"},{"t":"아린 — 「친구와 나는 좋아하는 색이 다르다.」","mis":"K2-1-u5-X17"}],"explanation":["몸에 상처를 입은 것은 「다쳐서」라고 써야 해요.","「닫히다」는 문 같은 것이 막히는 거예요.","은솔이와 아린이는 뜻에 맞게 바르게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#4','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'mc','auto','소리가 똑같이 나는 낱말끼리 짝지은 것은 어느 것인가요?',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":4,"concept":"K2-1-u5-C7","difficulty":3,"kind":"mc","stem":"소리가 똑같이 나는 낱말끼리 짝지은 것은 어느 것인가요?","options":[{"t":"걸음 · 거름","correct":true},{"t":"가르치다 · 가리키다","mis":"K2-1-u5-X10"},{"t":"잊다 · 잃다","mis":"K2-1-u5-X10"}],"explanation":["「걸음」과 「거름」은 둘 다 [거름]으로 소리 나요.","「가르치다」와 「가리키다」는 소리가 비슷하지만 같지 않아요.","「잊다」와 「잃다」도 소리가 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#5','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'ox','auto','「마치다」와 「맞히다」는 소리가 같지만 뜻이 서로 달라요.',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":3,"kind":"ox","stem":"「마치다」와 「맞히다」는 소리가 같지만 뜻이 서로 달라요.","answer":"O","reason_options":[{"t":"「마치다」는 일을 끝내다, 「맞히다」는 목표에 닿게 하다라는 뜻이니까","correct":true},{"t":"소리가 같으면 뜻도 같으니까","mis":"K2-1-u5-X09"}],"mis":"K2-1-u5-X09","explanation":["「수업을 마치다」, 「과녁을 맞히다」처럼 써요.","소리가 같아도 뜻이 다를 수 있어요.","문장의 뜻을 보고 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#6','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'mc','auto','「숙제를 (㉠) 친구와 공던지기를 했는데, 공으로 깡통을 (㉡).」 빈칸에 알맞은 말을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":6,"concept":"K2-1-u5-C7","difficulty":3,"kind":"mc","stem":"「숙제를 (㉠) 친구와 공던지기를 했는데, 공으로 깡통을 (㉡).」 빈칸에 알맞은 말을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"㉠ 마치고 · ㉡ 맞혔어요","correct":true},{"t":"㉠ 맞히고 · ㉡ 마쳤어요","mis":"K2-1-u5-X09"},{"t":"㉠ 마치고 · ㉡ 마쳤어요","mis":"K2-1-u5-X09"}],"explanation":["숙제를 끝내는 것은 「마치고」예요.","깡통에 공이 닿게 한 것은 「맞혔어요」예요.","두 빈칸의 뜻을 하나씩 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#7','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',3,'mc','auto','「깜빡하고 준비물을 챙기지 못했어요.」를 알맞게 바꾸어 쓴 것은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],false,'{"seq":7,"concept":"K2-1-u5-C7","difficulty":3,"kind":"mc","stem":"「깜빡하고 준비물을 챙기지 못했어요.」를 알맞게 바꾸어 쓴 것은 어느 것인가요?","options":[{"t":"「준비물 챙기는 것을 잊어버렸어요.」","correct":true},{"t":"「준비물 챙기는 것을 잃어버렸어요.」","mis":"K2-1-u5-X10"},{"t":"「준비물 챙기는 것을 잇어버렸어요.」","mis":"K2-1-u5-X09"}],"explanation":["깜빡하고 기억하지 못한 것은 「잊어버렸어요」예요.","「잃어버렸어요」는 물건이 없어졌을 때 써요.","「잇어버렸어요」는 없는 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#8','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',4,'mc','auto','「선생님께서 칠판의 글자를 손으로 가르치며 읽는 방법을 가리켜 주셨어요.」를 바르게 고친 것은 어느 것인가요?',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":8,"concept":"K2-1-u5-C7","difficulty":4,"kind":"mc","stem":"「선생님께서 칠판의 글자를 손으로 가르치며 읽는 방법을 가리켜 주셨어요.」를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「선생님께서 칠판의 글자를 손으로 가리키며 읽는 방법을 가르쳐 주셨어요.」","correct":true},{"t":"「선생님께서 칠판의 글자를 손으로 가르치며 읽는 방법을 가르쳐 주셨어요.」","mis":"K2-1-u5-X10"},{"t":"「선생님께서 칠판의 글자를 손으로 가리키며 읽는 방법을 가리켜 주셨어요.」","mis":"K2-1-u5-X10"}],"explanation":["손으로 짚어 보이는 것은 「가리키며」예요.","읽는 방법을 알려 주신 것은 「가르쳐」예요.","두 낱말의 자리가 바뀌어 있었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#9','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',4,'essay','teacher','「다르다」와 「틀리다」의 뜻이 어떻게 다른지 쓰고, 두 낱말을 하나씩 넣어 문장을 만들어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"「다르다」와 「틀리다」의 뜻이 어떻게 다른지 쓰고, 두 낱말을 하나씩 넣어 문장을 만들어 보세요.","answer_guide":{"answer":"예: 「다르다」는 같지 않다, 「틀리다」는 맞지 않다라는 뜻이에요. 내 필통과 네 필통은 색이 달라. 받아쓰기에서 한 문제가 틀렸어.","scoring_points":["「다르다」의 뜻을 바르게 썼는가","「틀리다」의 뜻을 바르게 썼는가","두 낱말을 뜻에 맞게 넣어 문장을 만들었는가"]},"explanation":["「다르다」의 뜻.","「틀리다」의 뜻.","뜻에 맞는 문장 두 개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L07_challenge#10','kor',2,1,'u5','L07','g2_1_kor_u5_L07_challenge','lesson_challenge','K2-1-u5-C7',4,'essay','teacher','헷갈리기 쉬운 낱말 짝(걸음·거름, 다치다·닫히다, 잊다·잃다 등) 하나를 골라 두 낱말의 뜻을 쓰고, 헷갈리지 않고 바르게 쓰는 방법을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":4,"kind":"essay","stem":"헷갈리기 쉬운 낱말 짝(걸음·거름, 다치다·닫히다, 잊다·잃다 등) 하나를 골라 두 낱말의 뜻을 쓰고, 헷갈리지 않고 바르게 쓰는 방법을 써 보세요.","answer_guide":{"answer":"예: 다치다는 몸에 상처를 입다, 닫히다는 열린 것이 막히다예요. 문장에서 몸 이야기인지 문 이야기인지 뜻을 생각하고 골라 써요.","scoring_points":["낱말 짝 하나를 골랐는가","두 낱말의 뜻을 바르게 썼는가","문장의 뜻을 생각하며 고른다는 방법을 썼는가"]},"explanation":["낱말 짝.","두 낱말의 뜻.","바르게 쓰는 방법."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#1','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',1,'mc','auto','자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],true,'{"seq":1,"concept":"K2-1-u5-C8","difficulty":1,"kind":"mc","stem":"자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「고양이가 / 햇볕에서 / 졸아요」","correct":true},{"t":"「고 / 양 / 이 / 가 / 햇볕에서 졸아요」","mis":"K2-1-u5-X11"},{"t":"「고양이가햇볕에서졸아요」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","한 글자씩 끊으면 어색하고 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 숨이 차요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「작은 새가 / 나뭇가지에 / 앉았다」","correct":true},{"t":"「작은 / 새 / 가 / 나뭇 / 가지에 앉았다」","mis":"K2-1-u5-X11"},{"t":"「작은새가나뭇가지에앉았다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","낱말마다 뚝뚝 끊으면 어색해요.","쉬지 않고 붙여 읽으면 숨이 차요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#2','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',1,'mc','auto','한 문장이 끝나고 다음 문장으로 넘어갈 때는 어떻게 쉬어 읽나요?',ARRAY['K2-1-u5-X14','K2-1-u5-X11']::text[],true,'{"seq":2,"concept":"K2-1-u5-C8","difficulty":1,"kind":"mc","stem":"한 문장이 끝나고 다음 문장으로 넘어갈 때는 어떻게 쉬어 읽나요?","options":[{"t":"문장 안에서보다 조금 더 길게 쉬어요","correct":true},{"t":"쉬지 않고 바로 이어 읽어요","mis":"K2-1-u5-X14"},{"t":"낱말마다 쉬어요","mis":"K2-1-u5-X11"}],"explanation":["문장과 문장 사이에서는 조금 더 길게 쉬어요.","바로 이어 읽으면 두 문장이 섞여 들려요.","낱말마다 쉬면 어색해요."],"variant_rule":{"alt":[{"stem":"「누가(무엇이)」에 해당하는 말 뒤에서는 어떻게 읽나요?","options":[{"t":"조금 쉬어 읽어요","correct":true},{"t":"쉬지 않고 붙여 읽어요","mis":"K2-1-u5-X14"},{"t":"한 글자씩 끊어 읽어요","mis":"K2-1-u5-X11"}],"explanation":["「토끼가 / 풀밭에서 놀아요」처럼 「누가」 뒤에서 조금 쉬어요.","붙여 읽으면 뜻 덩어리가 나뉘지 않아요.","한 글자씩 끊으면 어색해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#3','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',1,'ox','auto','낱말마다 뚝뚝 끊어 읽으면 글이 자연스럽게 들려요.',ARRAY['K2-1-u5-X11']::text[],true,'{"seq":3,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"낱말마다 뚝뚝 끊어 읽으면 글이 자연스럽게 들려요.","answer":"X","reason_options":[{"t":"뜻이 통하는 덩어리로 묶어 읽어야 자연스러우니까","correct":true},{"t":"낱말마다 끊어야 또박또박 들리니까","mis":"K2-1-u5-X11"}],"mis":"K2-1-u5-X11","explanation":["낱말마다 끊으면 뜻이 끊겨 어색해요.","뜻이 이어지는 부분은 붙여 읽어요.","덩어리 사이에서만 쉬어요."],"variant_rule":{"alt":[{"stem":"긴 문장을 한 번도 쉬지 않고 읽으면 숨이 차고 뜻을 알기 어려워요.","answer":"O","reason_options":[{"t":"뜻 덩어리 사이에서 쉬어야 숨도 고르고 뜻도 드러나니까","correct":true},{"t":"쉬지 않고 빨리 읽을수록 잘 읽은 것이니까","mis":"K2-1-u5-X12"}],"explanation":["쉬지 않으면 숨이 차고 듣는 사람도 알아듣기 어려워요.","뜻 덩어리 사이에서 쉬어요.","빨리 읽는 것과 잘 읽는 것은 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#4','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C9',1,'mc','auto','인물이 기쁜 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],true,'{"seq":4,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 기쁜 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"밝고 가볍게","correct":true},{"t":"차분하고 느리게","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["기쁜 장면은 밝고 가볍게 읽으면 마음이 살아나요.","차분하고 느린 목소리는 슬픈 장면에 어울려요.","화난 목소리는 기쁜 마음과 맞지 않아요."],"variant_rule":{"alt":[{"stem":"인물이 슬픈 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"차분하고 느리게","correct":true},{"t":"밝고 빠르게","mis":"K2-1-u5-X15"},{"t":"크게 소리 지르며","mis":"K2-1-u5-X15"}],"explanation":["슬픈 장면은 차분하고 느리게 읽으면 마음이 살아나요.","밝고 빠른 목소리는 기쁜 장면에 어울려요.","소리 지르면 슬픈 마음이 드러나지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#5','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',2,'match','auto','띄어 읽는 자리와 읽는 방법을 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C8","difficulty":2,"kind":"match","stem":"띄어 읽는 자리와 읽는 방법을 알맞게 이어 보세요.","pairs":[{"l":"「누가(무엇이)」에 해당하는 말 뒤","r":"조금 쉬기"},{"l":"문장과 문장 사이","r":"조금 더 길게 쉬기"},{"l":"뜻이 이어지는 낱말 사이","r":"붙여 읽기"}],"mis":"K2-1-u5-X14","explanation":["「누가」 뒤에서는 조금 쉬어요.","문장과 문장 사이에서는 조금 더 길게 쉬어요.","뜻이 이어지는 낱말은 붙여 읽어요."],"variant_rule":{"alt":[{"stem":"장면과 어울리는 읽는 방법을 이어 보세요.","pairs":[{"l":"기쁜 장면","r":"밝고 가볍게"},{"l":"슬픈 장면","r":"차분하고 느리게"},{"l":"떨리는 장면","r":"작고 조심스럽게"}],"explanation":["기쁜 장면은 밝고 가볍게 읽어요.","슬픈 장면은 차분하고 느리게 읽어요.","떨리는 장면은 작고 조심스럽게 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#6','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',2,'mc','auto','「나는 오늘 도서관에서 책을 읽었다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],true,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「나는 오늘 도서관에서 책을 읽었다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「나는 / 오늘 도서관에서 / 책을 읽었다」","correct":true},{"t":"「나 / 는 / 오늘 / 도서 / 관에서 / 책을 읽었다」","mis":"K2-1-u5-X11"},{"t":"「나는 오늘 도 / 서관에서 책을 / 읽었다」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","「도 / 서관」처럼 낱말 가운데에서 끊으면 뜻이 흐려져요."],"variant_rule":{"alt":[{"stem":"「비가 와서 우산을 썼다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「비가 와서 / 우산을 썼다」","correct":true},{"t":"「비가 / 와서우산을 / 썼다」","mis":"K2-1-u5-X13"},{"t":"「비 / 가 / 와 / 서 / 우산을 썼다」","mis":"K2-1-u5-X11"}],"explanation":["「비가 와서」와 「우산을 썼다」로 묶어 읽었어요.","「와서우산을」처럼 묶으면 뜻 덩어리가 흐트러져요.","한 글자씩 끊으면 어색해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#7','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C9',2,'blank','auto','「「엄마, 고마워요!」 하며 엄마를 꼭 안았어요.」를 인물의 마음을 살려 (     ) 목소리로 읽어요. 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],true,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":2,"kind":"blank","stem":"「「엄마, 고마워요!」 하며 엄마를 꼭 안았어요.」를 인물의 마음을 살려 (     ) 목소리로 읽어요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"따뜻하고 다정한","correct":true},{"t":"화나고 거친","mis":"K2-1-u5-X15"},{"t":"작고 졸린","mis":"K2-1-u5-X15"}],"explanation":["엄마를 꼭 안으며 고맙다고 하는 장면은 따뜻한 마음이에요.","화나고 거친 목소리는 고마운 마음과 맞지 않아요.","졸린 목소리로 읽으면 마음이 드러나지 않아요."],"variant_rule":{"alt":[{"stem":"「아끼던 화분이 깨져서 눈물이 났어요.」를 인물의 마음을 살려 (     ) 목소리로 읽어요. 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"차분하고 슬픈","correct":true},{"t":"밝고 신나는","mis":"K2-1-u5-X15"},{"t":"크고 씩씩한","mis":"K2-1-u5-X15"}],"explanation":["화분이 깨져 눈물이 나는 장면은 슬픈 마음이에요.","밝고 신나는 목소리는 슬픈 마음과 맞지 않아요.","크고 씩씩하게 읽으면 마음이 드러나지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#8','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',2,'sa','auto','띄어 읽을 곳을 표시할 때 긋는 「/」를 무엇이라고 하나요? 두 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C8","difficulty":2,"kind":"sa","stem":"띄어 읽을 곳을 표시할 때 긋는 「/」를 무엇이라고 하나요? 두 글자로 써 보세요.","answer":["빗금"],"explanation":["띄어 읽을 곳에 긋는 「/」를 빗금이라고 해요.","빗금이 있는 곳에서 조금 쉬어 읽어요.","빗금이 없는 곳은 붙여 읽어요."],"variant_rule":{"alt":[{"stem":"뜻이 통하는 덩어리로 띄어 읽으면 무엇이 잘 드러나나요? 한 글자로 써 보세요.","answer":["뜻"],"explanation":["알맞게 띄어 읽으면 뜻이 잘 드러나요.","듣는 사람도 뜻을 잘 알아들어요.","그래서 뜻 덩어리로 묶어 읽어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#9','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C9',2,'mc','auto','알맞게 띄어 읽으면서 인물의 마음도 살려 읽으면 좋은 점은 어느 것인가요?',ARRAY['K2-1-u5-X12','K2-1-u5-X15']::text[],true,'{"seq":9,"concept":"K2-1-u5-C9","difficulty":2,"kind":"mc","stem":"알맞게 띄어 읽으면서 인물의 마음도 살려 읽으면 좋은 점은 어느 것인가요?","options":[{"t":"듣는 사람이 뜻과 인물의 마음을 잘 느낄 수 있어요","correct":true},{"t":"글을 더 빨리 끝낼 수 있어요","mis":"K2-1-u5-X12"},{"t":"모든 장면을 같은 목소리로 읽을 수 있어요","mis":"K2-1-u5-X15"}],"explanation":["뜻도 마음도 잘 전해져 글이 살아나요.","빨리 끝내는 것이 목적이 아니에요.","장면마다 마음에 맞게 목소리를 바꾸어요."],"variant_rule":{"alt":[{"stem":"인물의 마음을 살려 읽기 전에 먼저 할 일은 무엇인가요?","options":[{"t":"장면 속 인물의 마음을 짐작해요","correct":true},{"t":"글자 수를 세어 봐요","mis":"K2-1-u5-X01"},{"t":"가장 큰 목소리를 정해요","mis":"K2-1-u5-X15"}],"explanation":["인물의 마음을 알아야 어울리는 목소리를 정할 수 있어요.","글자 수는 마음과 상관없어요.","큰 목소리가 언제나 어울리는 것은 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_basic#10','kor',2,1,'u5','L09','g2_1_kor_u5_L09_basic','lesson_basic','K2-1-u5-C8',3,'error','auto','「우리 반 친구들이 운동장에서 신나게 뛰어놀았다.」를 띄어 읽었어요. 어색하게 띄어 읽은 친구는 누구인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C8","difficulty":3,"kind":"error","stem":"「우리 반 친구들이 운동장에서 신나게 뛰어놀았다.」를 띄어 읽었어요. 어색하게 띄어 읽은 친구는 누구인가요?","options":[{"t":"지안 — 「우리 / 반 / 친 / 구들이 / 운동장에서 신나게 뛰어놀았다」","correct":true,"mis_target":"K2-1-u5-X11"},{"t":"도담 — 「우리 반 친구들이 / 운동장에서 / 신나게 뛰어놀았다」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「우리 반 친구들이 / 운동장에서 신나게 뛰어놀았다」","mis":"K2-1-u5-X17"}],"explanation":["지안이는 「친 / 구들이」처럼 낱말 가운데에서 끊어 어색해요.","도담이와 서윤이는 뜻 덩어리로 띄어 읽었어요.","띄어 읽는 곳이 조금 달라도 뜻이 드러나면 괜찮아요."],"variant_rule":{"alt":[{"stem":"「할머니께서 따뜻한 호박죽을 끓여 주셨다.」를 띄어 읽었어요. 어색하게 띄어 읽은 친구는 누구인가요?","options":[{"t":"현우 — 「할머니께서따뜻한호박죽을끓여주셨다」","correct":true,"mis_target":"K2-1-u5-X12"},{"t":"지우 — 「할머니께서 / 따뜻한 호박죽을 / 끓여 주셨다」","mis":"K2-1-u5-X17"},{"t":"하늘 — 「할머니께서 / 따뜻한 호박죽을 끓여 주셨다」","mis":"K2-1-u5-X17"}],"explanation":["현우는 한 번도 쉬지 않아 숨이 차고 뜻을 알기 어려워요.","지우와 하늘이는 뜻 덩어리로 띄어 읽었어요.","띄어 읽는 곳이 조금 달라도 뜻이 드러나면 괜찮아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#1','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',2,'mc','auto','「작은 / 새와 나무」로 띄어 읽으면 작은 것은 무엇인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":1,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「작은 / 새와 나무」로 띄어 읽으면 작은 것은 무엇인가요?","options":[{"t":"새와 나무 모두","correct":true},{"t":"새만","mis":"K2-1-u5-X13"},{"t":"나무만","mis":"K2-1-u5-X13"}],"explanation":["「작은 / 새와 나무」는 새와 나무가 모두 작다는 뜻이 돼요.","새만 작다면 「작은 새와 / 나무」로 읽어요.","어디에서 쉬느냐에 따라 뜻이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#2','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C9',2,'mc','auto','인물이 속상해서 「괜찮아…….」라고 말하는 장면은 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":2,"concept":"K2-1-u5-C9","difficulty":2,"kind":"mc","stem":"인물이 속상해서 「괜찮아…….」라고 말하는 장면은 어떻게 읽으면 좋을까요?","options":[{"t":"작고 느리게, 힘없는 목소리로","correct":true},{"t":"크고 밝은 목소리로","mis":"K2-1-u5-X15"},{"t":"빠르고 신나는 목소리로","mis":"K2-1-u5-X15"}],"explanation":["속상한 마음은 작고 힘없는 목소리에 잘 드러나요.","크고 밝게 읽으면 속상한 마음이 사라져요.","빠르고 신나게 읽으면 마음과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#3','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',3,'error','auto','자연스럽게 띄어 읽는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X12','K2-1-u5-X17']::text[],false,'{"seq":3,"concept":"K2-1-u5-C8","difficulty":3,"kind":"error","stem":"자연스럽게 띄어 읽는 방법을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"민호 — 「최대한 빠르게, 한 번도 쉬지 않고 읽어야 해.」","correct":true,"mis_target":"K2-1-u5-X12"},{"t":"하린 — 「뜻이 통하는 덩어리로 묶어 읽어.」","mis":"K2-1-u5-X17"},{"t":"지후 — 「문장과 문장 사이에서는 조금 더 길게 쉬어.」","mis":"K2-1-u5-X17"}],"explanation":["쉬지 않고 빨리 읽으면 숨이 차고 뜻을 알기 어려워요.","뜻 덩어리 사이에서 쉬어 읽어요.","하린이와 지후는 알맞게 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#4','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',3,'mc','auto','「엄마가 시장에서 사과를 사 오셨어요.」를 가장 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"「엄마가 시장에서 사과를 사 오셨어요.」를 가장 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「엄마가 / 시장에서 / 사과를 사 오셨어요」","correct":true},{"t":"「엄 / 마가 / 시 / 장에서 / 사과를 사 오셨어요」","mis":"K2-1-u5-X11"},{"t":"「엄마가시장에서사과를사오셨어요」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","낱말 가운데에서 끊으면 어색해요.","쉬지 않으면 숨이 차고 뜻을 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#5','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',3,'ox','auto','띄어 읽는 곳은 사람마다 조금 달라도 뜻이 잘 드러나면 괜찮아요.',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":5,"concept":"K2-1-u5-C8","difficulty":3,"kind":"ox","stem":"띄어 읽는 곳은 사람마다 조금 달라도 뜻이 잘 드러나면 괜찮아요.","answer":"O","reason_options":[{"t":"뜻 덩어리를 깨뜨리지 않으면 자연스럽게 들리니까","correct":true},{"t":"띄어 읽는 곳은 오직 한 가지뿐이니까","mis":"K2-1-u5-X13"}],"mis":"K2-1-u5-X13","explanation":["「우리 반 친구들이 / 운동장에서 / 놀았다」도, 「우리 반 친구들이 / 운동장에서 놀았다」도 괜찮아요.","낱말 가운데에서 끊거나 뜻이 바뀌게 끊으면 안 돼요.","뜻이 드러나는지가 가장 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#6','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C9',3,'mc','auto','글을 읽고 답해 보세요. 「무대 뒤에서 다리가 후들후들 떨렸어요.」를 아기 곰의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":6,"concept":"K2-1-u5-C9","difficulty":3,"kind":"mc","stem":"글을 읽고 답해 보세요. 「무대 뒤에서 다리가 후들후들 떨렸어요.」를 아기 곰의 마음을 살려 읽으려면 어떻게 읽으면 좋을까요?","options":[{"t":"작고 떨리는 목소리로 천천히","correct":true},{"t":"밝고 신나는 목소리로 빠르게","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["다리가 떨리는 장면은 떨리고 걱정되는 마음이에요.","밝고 신나게 읽으면 떨리는 마음이 드러나지 않아요.","화난 목소리는 이 장면과 맞지 않아요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#7','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',3,'mc','auto','「비가 그쳤어요. 하늘에 무지개가 떴어요.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X14','K2-1-u5-X11']::text[],false,'{"seq":7,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"「비가 그쳤어요. 하늘에 무지개가 떴어요.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「비가 그쳤어요. // 하늘에 / 무지개가 떴어요.」","correct":true},{"t":"「비가 그쳤어요. 하늘에무지개가 / 떴어요.」","mis":"K2-1-u5-X14"},{"t":"「비 / 가 / 그쳤어요. 하늘에 무지개가 떴어요.」","mis":"K2-1-u5-X11"}],"explanation":["두 문장 사이에서 조금 더 길게 쉬고, 뜻 덩어리로 묶어 읽었어요.","문장 사이에서 쉬지 않으면 두 문장이 섞여 들려요.","한 글자씩 끊으면 어색해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#8','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#9','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C8',4,'essay','teacher','「할머니께서 따뜻한 호박죽을 끓여 주셨어요.」에 「/」를 넣어 자연스럽게 띄어 읽을 곳을 표시하고, 그렇게 띄어 읽은 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C8","difficulty":4,"kind":"essay","stem":"「할머니께서 따뜻한 호박죽을 끓여 주셨어요.」에 「/」를 넣어 자연스럽게 띄어 읽을 곳을 표시하고, 그렇게 띄어 읽은 까닭을 써 보세요.","answer_guide":{"answer":"예: 할머니께서 / 따뜻한 호박죽을 / 끓여 주셨어요. — 뜻이 통하는 덩어리로 묶어 읽어야 뜻이 잘 드러나고 자연스럽기 때문이에요.","scoring_points":["「/」를 알맞은 곳에 넣었는가","낱말 가운데를 끊거나 너무 잘게 끊지 않았는가","뜻이 잘 드러난다는 까닭을 썼는가"]},"explanation":["알맞은 곳에 「/」.","뜻 덩어리 지키기.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L09_challenge#10','kor',2,1,'u5','L09','g2_1_kor_u5_L09_challenge','lesson_challenge','K2-1-u5-C9',4,'essay','teacher','「숲속 음악회」를 소리 내어 읽으려고 해요. 앞부분(무대 뒤)과 끝부분(손뼉을 칠 때)을 각각 어떤 목소리로 읽을지 쓰고, 그렇게 정한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C9","difficulty":4,"kind":"essay","stem":"「숲속 음악회」를 소리 내어 읽으려고 해요. 앞부분(무대 뒤)과 끝부분(손뼉을 칠 때)을 각각 어떤 목소리로 읽을지 쓰고, 그렇게 정한 까닭을 써 보세요.","answer_guide":{"answer":"예: 무대 뒤 장면은 작고 떨리는 목소리로 읽을래요. 아기 곰이 떨렸으니까요. 끝부분은 밝고 힘찬 목소리로 읽을래요. 아기 곰이 뿌듯했으니까요.","scoring_points":["앞부분의 목소리를 정해 썼는가","끝부분의 목소리를 정해 썼는가","아기 곰의 마음을 까닭으로 들었는가"]},"explanation":["앞부분 목소리.","끝부분 목소리.","마음을 까닭으로."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#1','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',1,'mc','auto','마음 사전에 적을 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],true,'{"seq":1,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"마음 사전에 적을 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"마음을 나타내는 말과 그 마음이 드는 상황","correct":true},{"t":"친구들의 전화번호","mis":"K2-1-u5-X05"},{"t":"좋아하는 음식 이름","mis":"K2-1-u5-X05"}],"explanation":["마음 사전에는 「뿌듯하다 — 줄넘기를 처음 성공했을 때」처럼 적어요.","전화번호나 음식 이름은 마음 말이 아니에요.","마음 말과 상황을 함께 적어요."],"variant_rule":{"alt":[{"stem":"마음을 나타내는 말을 많이 알면 어떤 점이 좋을까요?","options":[{"t":"내 마음을 더 잘 표현할 수 있어요","correct":true},{"t":"글자를 더 빨리 쓸 수 있어요","mis":"K2-1-u5-X05"},{"t":"친구의 마음을 몰라도 돼요","mis":"K2-1-u5-X16"}],"explanation":["마음 말을 많이 알면 내 마음을 알맞게 나타낼 수 있어요.","빨리 쓰는 것과는 상관없어요.","친구의 마음을 헤아리는 데도 도움이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#2','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',1,'mc','auto','친구가 무거운 짐을 함께 들어 주었어요. 친구에게 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],true,'{"seq":2,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 무거운 짐을 함께 들어 주었어요. 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「도와줘서 고마워.」","correct":true},{"t":"「몰라, 됐어.」","mis":"K2-1-u5-X16"},{"t":"「왜 이제 왔어?」","mis":"K2-1-u5-X16"}],"explanation":["도움을 받았을 때는 고마운 마음을 말로 전해요.","「몰라, 됐어.」에는 마음이 담겨 있지 않아요.","탓하는 말은 친구를 속상하게 해요."],"variant_rule":{"alt":[{"stem":"내가 실수로 친구의 발을 밟았어요. 친구에게 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「미안해, 많이 아프지?」","correct":true},{"t":"「네가 거기 서 있었잖아.」","mis":"K2-1-u5-X16"},{"t":"「하하, 괜찮지?」","mis":"K2-1-u5-X16"}],"explanation":["잘못했을 때는 미안한 마음을 말로 전하고 친구 마음을 살펴요.","친구를 탓하면 마음이 전해지지 않아요.","웃어넘기면 친구가 속상해요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#3','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',1,'ox','auto','「기분 나빠!」보다 「네가 내 말을 안 들어 줘서 서운했어.」라고 하면 마음이 더 잘 전해져요.',ARRAY['K2-1-u5-X16']::text[],true,'{"seq":3,"concept":"K2-1-u5-C10","difficulty":1,"kind":"ox","stem":"「기분 나빠!」보다 「네가 내 말을 안 들어 줘서 서운했어.」라고 하면 마음이 더 잘 전해져요.","answer":"O","reason_options":[{"t":"무슨 일 때문에 어떤 마음인지 정확히 알려 주니까","correct":true},{"t":"짧게 화를 내야 마음이 잘 전해지니까","mis":"K2-1-u5-X16"}],"mis":"K2-1-u5-X16","explanation":["「서운했어」처럼 마음 말로 정확히 말하면 친구가 잘 알아들어요.","무슨 일 때문인지도 함께 말해요.","화를 내면 마음이 잘 전해지지 않아요."],"variant_rule":{"alt":[{"stem":"친구가 「오늘 속상했어.」라고 할 때 「그게 뭐가 속상해?」라고 하면 친구의 마음을 헤아린 말이에요.","answer":"X","reason_options":[{"t":"「속상했겠다.」처럼 마음을 알아주는 말이 친구를 위로하니까","correct":true},{"t":"친구의 마음은 내가 정해 주어야 하니까","mis":"K2-1-u5-X16"}],"explanation":["「그게 뭐가 속상해?」는 친구의 마음을 무시하는 말이에요.","「속상했겠다.」처럼 마음을 알아주어요.","내가 그 말을 들으면 어떨지 떠올려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#4','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C5',1,'mc','auto','「소풍 가기 전날 밤」의 마음을 나타내는 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],true,'{"seq":4,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"「소풍 가기 전날 밤」의 마음을 나타내는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"서운하다","mis":"K2-1-u5-X06"},{"t":"미안하다","mis":"K2-1-u5-X06"}],"explanation":["기다리던 소풍을 앞두면 설레는 마음이 들어요.","「서운하다」는 섭섭할 때의 마음이에요.","「미안하다」는 잘못했을 때의 마음이에요."],"variant_rule":{"alt":[{"stem":"「상을 받았을 때」의 마음을 나타내는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"뿌듯하다","correct":true},{"t":"억울하다","mis":"K2-1-u5-X06"},{"t":"외롭다","mis":"K2-1-u5-X06"}],"explanation":["열심히 해서 상을 받으면 뿌듯한 마음이 들어요.","「억울하다」는 잘못 없이 혼날 때의 마음이에요.","「외롭다」는 혼자일 때의 마음이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#5','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',2,'match','auto','친구의 말과 마음을 헤아린 맞장구를 알맞게 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K2-1-u5-C10","difficulty":2,"kind":"match","stem":"친구의 말과 마음을 헤아린 맞장구를 알맞게 이어 보세요.","pairs":[{"l":"「할머니 댁에 못 가게 됐어.」","r":"「많이 아쉽겠다.」"},{"l":"「줄넘기 백 번 넘었어!」","r":"「우아, 정말 대단하다!」"},{"l":"「무서운 꿈을 꿨어.」","r":"「많이 놀랐겠다.」"}],"mis":"K2-1-u5-X16","explanation":["못 가게 된 친구에게는 아쉬운 마음을 알아주어요.","해낸 친구에게는 기쁨을 함께해요.","무서운 꿈을 꾼 친구에게는 놀란 마음을 알아주어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구의 말과 마음을 헤아린 맞장구를 알맞게 이어 보세요.","pairs":[{"l":"「강아지가 아파.」","r":"「많이 걱정되겠다.」"},{"l":"「상을 받았어!」","r":"「우아, 정말 축하해!」"},{"l":"「넘어져서 아파.」","r":"「많이 아팠겠다, 괜찮아?」"}],"explanation":["강아지가 아픈 친구에게는 걱정하는 마음을 알아주어요.","상을 받은 친구에게는 축하해요.","넘어진 친구에게는 아픈 마음을 살펴요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#6','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',2,'mc','auto','친구가 「동생이 내 그림을 찢었어.」라고 말했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],true,'{"seq":6,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「동생이 내 그림을 찢었어.」라고 말했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「정말 속상했겠다.」","correct":true},{"t":"「그림은 또 그리면 되잖아.」","mis":"K2-1-u5-X16"},{"t":"「하하, 재밌다!」","mis":"K2-1-u5-X16"}],"explanation":["친구의 속상한 마음을 알아주는 말이에요.","「또 그리면 되잖아」는 친구 마음을 가볍게 넘겨요.","웃으면 친구가 더 속상해요."],"variant_rule":{"alt":[{"stem":"친구가 「내일 이사 가서 전학 가.」라고 말했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「많이 섭섭하다. 가서도 꼭 연락하자.」","correct":true},{"t":"「잘됐네, 내 자리가 넓어지겠다.」","mis":"K2-1-u5-X16"},{"t":"「그래서 뭐?」","mis":"K2-1-u5-X16"}],"explanation":["헤어지는 섭섭한 마음을 함께 나누는 말이에요.","친구의 마음을 생각하지 않은 말은 속상하게 해요.","「그래서 뭐?」에는 마음이 담겨 있지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#7','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',2,'blank','auto','쪽지에 들어갈 마음 말로 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#8','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C5',2,'sa','auto','「앞으로 일어날 일이 기대되어 가슴이 두근거리다」라는 뜻의 마음 말을 세 글자로 써 보세요.','{}'::text[],true,'{"seq":8,"concept":"K2-1-u5-C5","difficulty":2,"kind":"sa","stem":"「앞으로 일어날 일이 기대되어 가슴이 두근거리다」라는 뜻의 마음 말을 세 글자로 써 보세요.","answer":["설레다"],"explanation":["소풍 전날처럼 기대될 때의 마음은 「설레다」예요.","「설레요」·「설레는」처럼 바꾸어 쓸 수 있어요.","마음 사전에 상황과 함께 적어 봐요."],"variant_rule":{"alt":[{"stem":"「일이 뜻대로 되지 않아 마음이 상하다」라는 뜻의 마음 말을 네 글자로 써 보세요.","answer":["속상하다"],"explanation":["아끼던 물건이 부서졌을 때처럼 마음이 상하는 것은 「속상하다」예요.","「속상해요」처럼 바꾸어 쓸 수 있어요.","마음 사전에 상황과 함께 적어 봐요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#9','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',2,'mc','auto','마음을 나타내는 말로 마음을 전하면 어떤 점이 좋을까요?',ARRAY['K2-1-u5-X16']::text[],true,'{"seq":9,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"마음을 나타내는 말로 마음을 전하면 어떤 점이 좋을까요?","options":[{"t":"서로의 마음을 잘 알아 더 가까워져요","correct":true},{"t":"친구가 내 말을 무조건 따라요","mis":"K2-1-u5-X16"},{"t":"마음은 말하지 않아야 더 잘 전해져요","mis":"K2-1-u5-X16"}],"explanation":["마음 말로 전하면 서로의 마음을 알게 돼요.","친구를 마음대로 하려는 것이 아니에요.","말하지 않으면 마음이 잘 전해지지 않아요."],"variant_rule":{"alt":[{"stem":"친구의 마음 말을 들었을 때 나는 어떻게 하면 좋을까요?","options":[{"t":"친구의 마음을 헤아려 알맞게 대답해요","correct":true},{"t":"못 들은 척하고 내 이야기만 해요","mis":"K2-1-u5-X16"},{"t":"친구의 마음이 틀렸다고 말해요","mis":"K2-1-u5-X16"}],"explanation":["친구의 마음을 헤아려 대답하면 친구가 위로받아요.","못 들은 척하면 친구가 서운해요.","마음은 맞고 틀린 것이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_basic#10','kor',2,1,'u5','L11','g2_1_kor_u5_L11_basic','lesson_basic','K2-1-u5-C10',3,'error','auto','서아의 말을 듣고 친구들이 대답했어요. 서아의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],true,'{"seq":10,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"서아의 말을 듣고 친구들이 대답했어요. 서아의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"민지 — 「그걸 왜 틀려? 쉬운 거잖아.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"로아 — 「많이 부끄러웠겠다. 나도 그런 적 있어.」","mis":"K2-1-u5-X17"},{"t":"지우 — 「괜찮아, 끝까지 발표한 게 멋졌어.」","mis":"K2-1-u5-X17"}],"explanation":["「그걸 왜 틀려?」는 서아를 더 부끄럽게 해요.","로아와 지우는 서아의 마음을 알아주었어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"오늘 발표하다가 틀려서 너무 부끄러웠어."}]},"variant_rule":{"alt":[{"stem":"하준이의 말을 듣고 친구들이 대답했어요. 하준이의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"시우 — 「강아지는 원래 자주 아파.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"예린 — 「많이 걱정되겠다.」","mis":"K2-1-u5-X17"},{"t":"도담 — 「강아지가 얼른 나으면 좋겠다.」","mis":"K2-1-u5-X17"}],"explanation":["「원래 자주 아파.」는 하준이의 걱정하는 마음을 알아주지 않아요.","예린이와 도담이는 하준이의 마음을 헤아렸어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"우리 강아지가 아파서 병원에 갔어."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#1','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',2,'mc','auto','마음 사전의 한 칸을 바르게 쓴 것은 어느 것인가요?',ARRAY['K2-1-u5-X06','K2-1-u5-X05']::text[],false,'{"seq":1,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"마음 사전의 한 칸을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"「뿌듯하다 — 줄넘기를 처음 백 번 넘었을 때」","correct":true},{"t":"「뿌듯하다 — 친구가 약속을 어겼을 때」","mis":"K2-1-u5-X06"},{"t":"「연필 — 글씨를 쓸 때」","mis":"K2-1-u5-X05"}],"explanation":["「뿌듯하다」는 무언가를 해냈을 때의 마음이에요.","약속을 어겼을 때는 「서운하다」가 어울려요.","「연필」은 마음 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#2','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',2,'mc','auto','「기분 나빠!」를 마음이 더 잘 전해지게 바꾼 말은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":2,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"「기분 나빠!」를 마음이 더 잘 전해지게 바꾼 말은 어느 것인가요?","options":[{"t":"「네가 내 차례를 건너뛰어서 서운했어.」","correct":true},{"t":"「몰라, 됐어.」","mis":"K2-1-u5-X16"},{"t":"「너랑 다시는 안 놀아!」","mis":"K2-1-u5-X16"}],"explanation":["무슨 일 때문에 어떤 마음인지 마음 말로 정확히 말했어요.","「몰라, 됐어.」에는 마음이 담겨 있지 않아요.","화를 내는 말은 마음을 잘 전하지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#3','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C5',3,'error','auto','마음 말을 넣어 문장을 만들었어요. 마음 말을 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X06','K2-1-u5-X17']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":3,"kind":"error","stem":"마음 말을 넣어 문장을 만들었어요. 마음 말을 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"하람 — 「내일 놀이공원에 가서 너무 서운해.」","correct":true,"mis_target":"K2-1-u5-X06"},{"t":"현우 — 「친구가 도와줘서 고마웠어.」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「짝이 전학 가서 섭섭해.」","mis":"K2-1-u5-X17"}],"explanation":["놀이공원에 가기 전에는 「설레다」가 어울려요.","「서운하다」는 섭섭할 때의 마음이에요.","현우와 서윤이는 알맞게 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#4','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',3,'mc','auto','대화를 읽고 답해 보세요. 도윤이에게 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":4,"concept":"K2-1-u5-C10","difficulty":3,"kind":"mc","stem":"대화를 읽고 답해 보세요. 도윤이에게 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「많이 서운했겠다. 다음엔 나랑 같이 가자.」","correct":true},{"t":"「그런 일로 뭘 그래.」","mis":"K2-1-u5-X16"},{"t":"「나도 같이 갔었는데 정말 재밌었어!」","mis":"K2-1-u5-X16"}],"explanation":["도윤이의 서운한 마음을 알아주고 함께하자고 했어요.","「뭘 그래」는 도윤이의 마음을 무시하는 말이에요.","자랑하면 도윤이가 더 서운해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"나만 빼고 다 같이 놀러 갔대……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#5','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',3,'ox','auto','쪽지에 마음을 나타내는 말을 넣으면 받는 친구가 내 마음을 더 잘 알 수 있어요.',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":5,"concept":"K2-1-u5-C10","difficulty":3,"kind":"ox","stem":"쪽지에 마음을 나타내는 말을 넣으면 받는 친구가 내 마음을 더 잘 알 수 있어요.","answer":"O","reason_options":[{"t":"「고마웠어」·「미안해」처럼 마음이 분명하게 드러나니까","correct":true},{"t":"마음 말은 쪽지에 쓰지 않는 것이 좋으니까","mis":"K2-1-u5-X16"}],"mis":"K2-1-u5-X16","explanation":["마음 말을 넣으면 마음이 분명해져요.","받는 친구가 내 마음을 잘 알 수 있어요.","있었던 일도 함께 쓰면 더 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#6','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C5',3,'mc','auto','뜻이 비슷한 마음 말끼리 짝지은 것은 어느 것인가요?',ARRAY['K2-1-u5-X06']::text[],false,'{"seq":6,"concept":"K2-1-u5-C5","difficulty":3,"kind":"mc","stem":"뜻이 비슷한 마음 말끼리 짝지은 것은 어느 것인가요?","options":[{"t":"서운하다 · 섭섭하다","correct":true},{"t":"서운하다 · 설레다","mis":"K2-1-u5-X06"},{"t":"고맙다 · 미안하다","mis":"K2-1-u5-X06"}],"explanation":["「서운하다」와 「섭섭하다」는 비슷한 마음이에요.","「설레다」는 기대될 때의 마음이에요.","「고맙다」와 「미안하다」는 서로 다른 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#7','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',3,'mc','auto','친구가 「받아쓰기 백 점 받았어!」라고 했어요. 마음을 헤아린 대답으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":7,"concept":"K2-1-u5-C10","difficulty":3,"kind":"mc","stem":"친구가 「받아쓰기 백 점 받았어!」라고 했어요. 마음을 헤아린 대답으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「우아, 정말 기쁘겠다! 열심히 연습하더니 멋지다.」","correct":true},{"t":"「나도 전에 백 점 받았거든.」","mis":"K2-1-u5-X16"},{"t":"「이번 받아쓰기는 쉬웠잖아.」","mis":"K2-1-u5-X16"}],"explanation":["친구의 기쁜 마음을 함께 나누는 말이에요.","내 자랑만 하면 친구의 기쁨을 알아주지 못해요.","쉬웠다고 하면 친구가 서운해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#8','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',4,'mc','auto','마음을 담은 쪽지에 들어갈 것으로 모두 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X05']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":4,"kind":"mc","stem":"마음을 담은 쪽지에 들어갈 것으로 모두 알맞은 것은 어느 것인가요?","options":[{"t":"받는 사람 · 있었던 일 · 내 마음을 나타내는 말","correct":true},{"t":"받는 사람 · 친구 흉 · 내 마음","mis":"K2-1-u5-X16"},{"t":"오늘 날씨 · 급식 메뉴 · 시간표","mis":"K2-1-u5-X05"}],"explanation":["누구에게, 무슨 일로, 어떤 마음인지 써야 마음이 잘 전해져요.","친구 흉은 마음을 전하는 쪽지에 어울리지 않아요.","날씨나 급식 메뉴는 마음을 전하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#9','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',4,'essay','teacher','고마웠거나 미안했던 친구에게 마음을 담은 쪽지를 써 보세요. 받는 사람, 있었던 일, 마음을 나타내는 말이 들어가게 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C10","difficulty":4,"kind":"essay","stem":"고마웠거나 미안했던 친구에게 마음을 담은 쪽지를 써 보세요. 받는 사람, 있었던 일, 마음을 나타내는 말이 들어가게 써 보세요.","answer_guide":{"answer":"예: 하린아, 어제 내가 넘어졌을 때 일으켜 줘서 정말 고마웠어. 다음엔 내가 꼭 도와줄게.","scoring_points":["받는 사람을 썼는가","있었던 일을 썼는가","마음을 나타내는 말을 넣었는가"]},"explanation":["받는 사람.","있었던 일.","마음 말."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_L11_challenge#10','kor',2,1,'u5','L11','g2_1_kor_u5_L11_challenge','lesson_challenge','K2-1-u5-C10',4,'essay','teacher','친구가 「오늘 속상했어.」라고 말했어요. 친구의 마음을 헤아려 어떻게 대답할지 두 문장으로 쓰고, 그렇게 대답한 까닭을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-1-u5-C10","difficulty":4,"kind":"essay","stem":"친구가 「오늘 속상했어.」라고 말했어요. 친구의 마음을 헤아려 어떻게 대답할지 두 문장으로 쓰고, 그렇게 대답한 까닭을 써 보세요.","answer_guide":{"answer":"예: 「많이 속상했겠다. 무슨 일 있었어?」 — 친구의 마음을 먼저 알아주면 친구가 위로받고 이야기를 꺼낼 수 있기 때문이에요.","scoring_points":["친구의 마음을 알아주는 맞장구를 썼는가","두 문장으로 썼는가","마음을 헤아려 대답한 까닭을 썼는가"]},"explanation":["맞장구.","두 문장.","까닭."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#1','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C1',1,'mc','auto','다른 사람의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X01']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"다른 사람의 마음을 짐작할 때 살펴볼 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"말 · 행동 · 표정 · 상황","correct":true},{"t":"옷 색깔 · 키 · 신발","mis":"K2-1-u5-X01"},{"t":"이름 · 나이 · 머리 모양","mis":"K2-1-u5-X01"}],"explanation":["마음은 말·행동·표정·상황에서 드러나요.","생김새·옷·이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#2','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C3',1,'mc','auto','「드디어 됐다!」 하며 두 손을 번쩍 들었어요. 이 인물의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"「드디어 됐다!」 하며 두 손을 번쩍 들었어요. 이 인물의 마음은 어느 것인가요?","options":[{"t":"기쁜 마음","correct":true},{"t":"속상한 마음","mis":"K2-1-u5-X02"},{"t":"무서운 마음","mis":"K2-1-u5-X02"}],"explanation":["두 손을 번쩍 드는 행동에서 기쁜 마음이 드러나요.","다른 마음은 이 말·행동과 맞지 않아요.","행동을 따라 해 보며 마음을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#3','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"설레다","correct":true},{"t":"연필","mis":"K2-1-u5-X05"},{"t":"운동장","mis":"K2-1-u5-X05"}],"explanation":["「설레다」는 마음을 나타내는 말이에요.","「연필」·「운동장」은 물건·장소·움직임을 나타내요.","「나는 지금 ○○해.」에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#4','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「동생이 / 우유를 / 마신다」","correct":true},{"t":"「동 / 생이우 / 유를 마신다」","mis":"K2-1-u5-X11"},{"t":"「동생이우유를마신다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#5','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',1,'mc','auto','「걸음」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「걸음」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"발을 옮겨 걷는 것","correct":true},{"t":"식물을 잘 자라게 하는 흙","mis":"K2-1-u5-X09"},{"t":"하던 일을 끝내는 것","mis":"K2-1-u5-X09"}],"explanation":["「걸음」은 발을 옮겨 걷는 것는 뜻이에요.","다른 뜻은 소리가 같거나 비슷한 다른 낱말의 뜻이에요.","소리가 같아도 뜻을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#6','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C8',1,'ox','auto','낱말마다 뚝뚝 끊어 읽으면 글이 자연스럽게 들려요.',ARRAY['K2-1-u5-X11']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"낱말마다 뚝뚝 끊어 읽으면 글이 자연스럽게 들려요.","answer":"X","reason_options":[{"t":"뜻이 통하는 덩어리로 묶어 읽어야 자연스러우니까","correct":true},{"t":"낱말마다 끊어야 또박또박 들리니까","mis":"K2-1-u5-X11"}],"mis":"K2-1-u5-X11","explanation":["낱말마다 끊으면 뜻이 끊겨 어색해요.","뜻이 통하는 덩어리로 묶어 읽어요.","그러면 물 흐르듯 자연스럽게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#7','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C9',1,'mc','auto','인물이 기쁜 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 기쁜 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"밝고 가볍게","correct":true},{"t":"차분하고 느리게","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["인물이 기쁜 장면은 밝고 가볍게 읽으면 마음이 살아나요.","다른 목소리는 이 장면의 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#8','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C10',1,'mc','auto','친구가 무거운 짐을 함께 들어 주었어요. 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 무거운 짐을 함께 들어 주었어요. 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「도와줘서 고마워.」","correct":true},{"t":"「몰라, 됐어.」","mis":"K2-1-u5-X16"},{"t":"「왜 이제 왔어?」","mis":"K2-1-u5-X16"}],"explanation":["도움을 받았을 때는 고마운 마음을 전해요.","마음이 담기지 않은 말이나 탓하는 말은 친구를 속상하게 해요.","마음 말로 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#9','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"생일 선물을 받았을 때","r":"기쁘다"},{"l":"아끼던 장난감이 부서졌을 때","r":"속상하다"},{"l":"내일 소풍을 가기로 했을 때","r":"설레다"}],"mis":"K2-1-u5-X03","explanation":["「생일 선물을 받았을 때」 — 기쁘다","「아끼던 장난감이 부서졌을 때」 — 속상하다","「내일 소풍을 가기로 했을 때」 — 설레다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#10','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',2,'blank','auto','「텃밭의 상추가 잘 자라도록 (     )을 주었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「텃밭의 상추가 잘 자라도록 (     )을 주었어요.」 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"거름","correct":true},{"t":"걸음","mis":"K2-1-u5-X09"},{"t":"거럼","mis":"K2-1-u5-X09"}],"explanation":["식물을 잘 자라게 하는 흙은 「거름」이에요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#11','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 지안이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":11,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"무섭다 → 용기를 내다 → 신나다","correct":true},{"t":"신나다 → 무섭다 → 용기를 내다","mis":"K2-1-u5-X07"},{"t":"무섭다 → 무섭다 → 무섭다","mis":"K2-1-u5-X07"}],"explanation":["처음에는 무서웠고, 하람이 말에 용기를 내었고, 나중에는 신났어요.","차례를 뒤바꾸거나 마음이 그대로라고 보면 안 돼요.","처음 → 무슨 일 → 나중을 따라가요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#12','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 서준이가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":12,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이가 속상한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"입술을 삐죽 내밀었어요","correct":true},{"t":"「와, 해냈다!」 하며 손뼉을 쳤어요","mis":"K2-1-u5-X02"},{"t":"종이비행기를 접었어요","mis":"K2-1-u5-X08"}],"explanation":["입술을 삐죽 내미는 행동에 속상한 마음이 드러나요.","다른 마음이 드러난 부분이나 일어난 일과 헷갈리지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#13','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',2,'ox','auto','「종이 울려서 수업을 맞혔어요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":13,"concept":"K2-1-u5-C7","difficulty":2,"kind":"ox","stem":"「종이 울려서 수업을 맞혔어요.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"하던 일을 끝내는 것은 「마치다」라서 「마쳤어요」라고 써야 하니까","correct":true},{"t":"소리가 같으면 아무 낱말이나 써도 되니까","mis":"K2-1-u5-X09"}],"mis":"K2-1-u5-X09","explanation":["수업을 끝내는 것은 「마치다」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#14','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C8',2,'mc','auto','「나는 오늘 도서관에서 책을 읽었다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":14,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「나는 오늘 도서관에서 책을 읽었다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「나는 / 오늘 도서관에서 / 책을 읽었다」","correct":true},{"t":"「나 / 는 / 오늘 / 도서 / 관에서 / 책을 읽었다」","mis":"K2-1-u5-X11"},{"t":"「나는 오늘 도 / 서관에서 책을 / 읽었다」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","낱말 가운데에서 끊거나 덩어리를 흩뜨리면 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#15','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C10',2,'mc','auto','친구가 「동생이 내 그림을 찢었어.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":15,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「동생이 내 그림을 찢었어.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「정말 속상했겠다.」","correct":true},{"t":"「그림은 또 그리면 되잖아.」","mis":"K2-1-u5-X16"},{"t":"「하하, 재밌다!」","mis":"K2-1-u5-X16"}],"explanation":["친구의 속상한 마음을 알아주는 말이에요.","친구의 마음을 가볍게 넘기거나 놀리는 말은 친구를 더 속상하게 해요.","내가 그 말을 들으면 어떨지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#16','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C5',2,'match','auto','마음을 나타내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"마음을 나타내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"설레다","r":"앞으로 일어날 일이 기대되어 두근거리다"},{"l":"뿌듯하다","r":"해낸 일이 자랑스러워 마음이 꽉 차다"},{"l":"서운하다","r":"바라던 대로 되지 않아 섭섭하다"}],"mis":"K2-1-u5-X06","explanation":["「설레다」 — 앞으로 일어날 일이 기대되어 두근거리다","「뿌듯하다」 — 해낸 일이 자랑스러워 마음이 꽉 차다","「서운하다」 — 바라던 대로 되지 않아 섭섭하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#17','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X09','K2-1-u5-X17']::text[],false,'{"seq":17,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"하준 — 「반듯이 숙제를 하고 놀 거예요.」","correct":true,"mis_target":"K2-1-u5-X09"},{"t":"예린 — 「의자에 반듯이 앉았어요.」","mis":"K2-1-u5-X17"},{"t":"소율 — 「숙제를 마치고 놀았어요.」","mis":"K2-1-u5-X17"}],"explanation":["「꼭」이라는 뜻은 「반드시」라고 써야 해요.","다른 두 친구는 뜻에 맞게 바르게 썼어요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#18','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C6',3,'error','auto','글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],false,'{"seq":18,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「지안이는 처음부터 수영장이 하나도 무섭지 않았어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"예린 — 「처음에는 엄마 손을 꼭 잡을 만큼 무서웠어.」","mis":"K2-1-u5-X17"},{"t":"현우 — 「나중에는 물장구를 치며 신났어.」","mis":"K2-1-u5-X17"}],"explanation":["지안이는 처음에 물이 깊어 보여 무서워했어요.","마음은 처음 그대로 있지 않고 일에 따라 바뀌었어요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#19','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C8',3,'mc','auto','물을 달라는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":19,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"물을 달라는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「나 / 물 좀 주세요」","correct":true},{"t":"「나물 / 좀 주세요」","mis":"K2-1-u5-X13"},{"t":"「나물좀 / 주세요」","mis":"K2-1-u5-X13"}],"explanation":["「나 / 물 좀 주세요」로 읽어야 물을 달라는 뜻이 돼요.","어디에서 쉬느냐에 따라 뜻이 달라져요.","끊어 읽은 대로 그림을 떠올려 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#20','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C4',3,'mc','auto','「언니가 쌓은 블록 탑을 동생이 실수로 무너뜨렸어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":20,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"「언니가 쌓은 블록 탑을 동생이 실수로 무너뜨렸어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"언니는 속상하고, 동생은 미안해요","correct":true},{"t":"언니는 미안하고, 동생은 속상해요","mis":"K2-1-u5-X04"},{"t":"언니는 신나고, 동생은 뿌듯해요","mis":"K2-1-u5-X03"}],"explanation":["탑이 무너진 언니는 속상하고, 무너뜨린 동생은 미안할 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#21','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C10',3,'error','auto','친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],false,'{"seq":21,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"민지 — 「그걸 왜 틀려? 쉬운 거잖아.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"로아 — 「많이 부끄러웠겠다. 나도 그런 적 있어.」","mis":"K2-1-u5-X17"},{"t":"지우 — 「괜찮아, 끝까지 발표한 게 멋졌어.」","mis":"K2-1-u5-X17"}],"explanation":["「그걸 왜 틀려?」는 서아를 더 부끄럽게 해요.","다른 두 친구는 마음을 알아주는 맞장구를 쳤어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"오늘 발표하다가 틀려서 너무 부끄러웠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#22','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C3',3,'mc','auto','「괜찮아.」라고 말하면서 손으로 눈물을 훔쳤어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":22,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「괜찮아.」라고 말하면서 손으로 눈물을 훔쳤어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 괜찮다고 했지만 사실은 속상한 마음","correct":true},{"t":"말 그대로 정말 괜찮고 기쁜 마음","mis":"K2-1-u5-X02"},{"t":"졸리고 심심한 마음","mis":"K2-1-u5-X03"}],"explanation":["눈물을 훔치는 행동에서 속상한 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","다른 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#23','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#24','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C7',4,'essay','teacher','다음 문장에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 낱말의 뜻을 들어 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_a#25','kor',2,1,'u5','','g2_1_kor_u5_review_a','unit_review','K2-1-u5-C6',4,'essay','teacher','글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.","answer_guide":{"answer":"예: 처음에는 무서웠어요(엄마 손을 꼭 잡음). 하람이가 같이 들어가자고 해서 용기를 냈고, 끝에는 신났어요(깔깔 웃으며 물장구).","scoring_points":["처음과 끝의 마음을 마음 말로 썼는가","마음이 바뀐 까닭을 글에서 찾아 썼는가","근거가 된 말이나 행동을 썼는가"]},"explanation":["처음과 끝의 마음.","바뀐 까닭.","근거."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#1','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C1',1,'mc','auto','「마음 짐작하기」를 바르게 말한 것은 어느 것인가요?',ARRAY['K2-1-u5-X01']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"「마음 짐작하기」를 바르게 말한 것은 어느 것인가요?","options":[{"t":"말과 행동을 보고 어떤 마음인지 헤아리는 것","correct":true},{"t":"얼굴 생김새로 이름을 맞히는 것","mis":"K2-1-u5-X01"},{"t":"친구의 키를 재어 보는 것","mis":"K2-1-u5-X01"}],"explanation":["마음 짐작은 말·행동·표정·상황을 보고 마음을 헤아리는 거예요.","생김새·옷·이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#2','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C3',1,'mc','auto','고개를 푹 숙이고 작은 목소리로 「미안해.」 했어요. 이 인물의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"고개를 푹 숙이고 작은 목소리로 「미안해.」 했어요. 이 인물의 마음은 어느 것인가요?","options":[{"t":"미안한 마음","correct":true},{"t":"신나는 마음","mis":"K2-1-u5-X02"},{"t":"뿌듯한 마음","mis":"K2-1-u5-X02"}],"explanation":["고개를 숙이고 「미안해.」 한 말과 행동에서 미안한 마음이 드러나요.","다른 마음은 이 말·행동과 맞지 않아요.","행동을 따라 해 보며 마음을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#3','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"뿌듯하다","correct":true},{"t":"의자","mis":"K2-1-u5-X05"},{"t":"달리다","mis":"K2-1-u5-X05"}],"explanation":["「뿌듯하다」는 마음을 나타내는 말이에요.","「의자」·「달리다」는 물건·장소·움직임을 나타내요.","「나는 지금 ○○해.」에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#4','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「하늘에 / 무지개가 / 떴다」","correct":true},{"t":"「하 / 늘에무 / 지개가 떴다」","mis":"K2-1-u5-X11"},{"t":"「하늘에무지개가떴다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#5','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',1,'mc','auto','「다치다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「다치다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸에 상처를 입다","correct":true},{"t":"열려 있던 것이 막히다","mis":"K2-1-u5-X09"},{"t":"목표에 닿게 하다","mis":"K2-1-u5-X09"}],"explanation":["「다치다」는 몸에 상처를 입다는 뜻이에요.","다른 뜻은 소리가 같거나 비슷한 다른 낱말의 뜻이에요.","소리가 같아도 뜻을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#6','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C8',1,'ox','auto','긴 문장을 한 번도 쉬지 않고 읽으면 숨이 차고 뜻을 알기 어려워요.',ARRAY['K2-1-u5-X12']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"긴 문장을 한 번도 쉬지 않고 읽으면 숨이 차고 뜻을 알기 어려워요.","answer":"O","reason_options":[{"t":"뜻 덩어리 사이에서 쉬어야 숨도 고르고 뜻도 드러나니까","correct":true},{"t":"쉬지 않고 빨리 읽을수록 잘 읽은 것이니까","mis":"K2-1-u5-X12"}],"mis":"K2-1-u5-X12","explanation":["쉬지 않으면 듣는 사람도 알아듣기 어려워요.","뜻이 통하는 덩어리로 묶어 읽어요.","그러면 물 흐르듯 자연스럽게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#7','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C9',1,'mc','auto','인물이 슬픈 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 슬픈 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"차분하고 느리게","correct":true},{"t":"밝고 빠르게","mis":"K2-1-u5-X15"},{"t":"크게 소리 지르며","mis":"K2-1-u5-X15"}],"explanation":["인물이 슬픈 장면은 차분하고 느리게 읽으면 마음이 살아나요.","다른 목소리는 이 장면의 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#8','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C10',1,'mc','auto','내가 실수로 친구의 발을 밟았어요. 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"내가 실수로 친구의 발을 밟았어요. 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「미안해, 많이 아프지?」","correct":true},{"t":"「네가 거기 서 있었잖아.」","mis":"K2-1-u5-X16"},{"t":"「하하, 괜찮지?」","mis":"K2-1-u5-X16"}],"explanation":["잘못했을 때는 미안한 마음을 전해요.","마음이 담기지 않은 말이나 탓하는 말은 친구를 속상하게 해요.","마음 말로 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#9','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"친구가 넘어진 나를 일으켜 주었을 때","r":"고맙다"},{"l":"내가 친구 발을 밟았을 때","r":"미안하다"},{"l":"발표 차례를 기다릴 때","r":"떨리다"}],"mis":"K2-1-u5-X03","explanation":["「친구가 넘어진 나를 일으켜 주었을 때」 — 고맙다","「내가 친구 발을 밟았을 때」 — 미안하다","「발표 차례를 기다릴 때」 — 떨리다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#10','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',2,'blank','auto','「선생님께서 우리에게 한글을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「선생님께서 우리에게 한글을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"가르쳐 주셨어요","correct":true},{"t":"가리켜 주셨어요","mis":"K2-1-u5-X10"},{"t":"가르켜 주셨어요","mis":"K2-1-u5-X09"}],"explanation":["모르는 것을 알려 주는 것은 「가르치다」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#11','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 아기 곰의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":11,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 아기 곰의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"떨리다 → 힘이 나다 → 뿌듯하다","correct":true},{"t":"뿌듯하다 → 떨리다 → 힘이 나다","mis":"K2-1-u5-X07"},{"t":"떨리다 → 떨리다 → 떨리다","mis":"K2-1-u5-X07"}],"explanation":["처음에는 떨렸고, 다람쥐 응원에 힘이 났고, 나중에는 뿌듯했어요.","차례를 뒤바꾸거나 마음이 그대로라고 보면 안 돼요.","처음 → 무슨 일 → 나중을 따라가요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#12','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 동생이 미안한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":12,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 동생이 미안한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"고개를 숙이고 「언니, 미안해.」 했어요","correct":true},{"t":"할머니가 활짝 웃으셨어요","mis":"K2-1-u5-X02"},{"t":"할머니 생신 선물로 카드를 만들었어요","mis":"K2-1-u5-X08"}],"explanation":["고개를 숙이고 「미안해.」 한 말과 행동에 미안한 마음이 드러나요.","다른 마음이 드러난 부분이나 일어난 일과 헷갈리지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#13','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',2,'ox','auto','「넘어져서 무릎을 다쳤어요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":13,"concept":"K2-1-u5-C7","difficulty":2,"kind":"ox","stem":"「넘어져서 무릎을 다쳤어요.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"몸에 상처를 입은 것은 「다치다」니까","correct":true},{"t":"소리가 같으면 「닫혔어요」라고 써도 되니까","mis":"K2-1-u5-X09"}],"mis":"K2-1-u5-X09","explanation":["몸에 상처를 입는 것은 「다치다」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#14','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C8',2,'mc','auto','「비가 와서 우산을 썼다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":14,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「비가 와서 우산을 썼다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「비가 와서 / 우산을 썼다」","correct":true},{"t":"「비 / 가 / 와 / 서 / 우산을 썼다」","mis":"K2-1-u5-X11"},{"t":"「비가 / 와서우산을 / 썼다」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","낱말 가운데에서 끊거나 덩어리를 흩뜨리면 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#15','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C10',2,'mc','auto','친구가 「우리 강아지가 아파.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":15,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「우리 강아지가 아파.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「많이 걱정되겠다.」","correct":true},{"t":"「강아지는 원래 자주 아파.」","mis":"K2-1-u5-X16"},{"t":"「나는 강아지 안 좋아해.」","mis":"K2-1-u5-X16"}],"explanation":["친구의 걱정하는 마음을 알아주는 말이에요.","친구의 마음을 가볍게 넘기거나 놀리는 말은 친구를 더 속상하게 해요.","내가 그 말을 들으면 어떨지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#16','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C5',2,'match','auto','마음을 나타내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"마음을 나타내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"미안하다","r":"남에게 잘못하여 마음이 편하지 않다"},{"l":"고맙다","r":"남이 베풀어 준 일에 마음이 흐뭇하다"},{"l":"속상하다","r":"일이 뜻대로 되지 않아 마음이 상하다"}],"mis":"K2-1-u5-X06","explanation":["「미안하다」 — 남에게 잘못하여 마음이 편하지 않다","「고맙다」 — 남이 베풀어 준 일에 마음이 흐뭇하다","「속상하다」 — 일이 뜻대로 되지 않아 마음이 상하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#17','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X17']::text[],false,'{"seq":17,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"지호 — 「놀이터에서 장갑을 잊어버렸어요.」","correct":true,"mis_target":"K2-1-u5-X10"},{"t":"다은 — 「친구 생일을 잊지 않았어요.」","mis":"K2-1-u5-X17"},{"t":"시우 — 「공원에서 모자를 잃어버렸어요.」","mis":"K2-1-u5-X17"}],"explanation":["물건이 없어진 것은 「잃어버렸어요」라고 써야 해요.","다른 두 친구는 뜻에 맞게 바르게 썼어요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#18','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C6',3,'error','auto','글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],false,'{"seq":18,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"지우 — 「아기 곰은 처음부터 하나도 떨리지 않았어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"도담 — 「무대 뒤에서는 다리가 떨렸어.」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「나중에는 가슴을 펴고 웃었어.」","mis":"K2-1-u5-X17"}],"explanation":["아기 곰은 무대 뒤에서 다리가 후들후들 떨렸어요.","마음은 처음 그대로 있지 않고 일에 따라 바뀌었어요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#19','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C8',3,'mc','auto','아빠가 방에 들어가신다는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":19,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"아빠가 방에 들어가신다는 뜻이 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「아빠가 / 방에 들어가신다」","correct":true},{"t":"「아빠 / 가방에 들어가신다」","mis":"K2-1-u5-X13"},{"t":"「아빠가방 / 에 들어가신다」","mis":"K2-1-u5-X13"}],"explanation":["「아빠가 / 방에」로 끊어야 아빠가 방에 들어가신다는 뜻이 돼요.","어디에서 쉬느냐에 따라 뜻이 달라져요.","끊어 읽은 대로 그림을 떠올려 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#20','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C4',3,'mc','auto','「동생이 꽃병을 깨뜨렸는데 형이 대신 혼났어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":20,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"「동생이 꽃병을 깨뜨렸는데 형이 대신 혼났어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"형은 억울하고, 동생은 미안해요","correct":true},{"t":"형은 미안하고, 동생은 억울해요","mis":"K2-1-u5-X04"},{"t":"형은 설레고, 동생은 신나요","mis":"K2-1-u5-X03"}],"explanation":["대신 혼난 형은 억울하고, 깨뜨린 동생은 미안할 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#21','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C10',3,'error','auto','친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],false,'{"seq":21,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"시우 — 「그런 일로 뭘 그래.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"하린 — 「많이 서운했겠다.」","mis":"K2-1-u5-X17"},{"t":"지안 — 「다음엔 나랑 같이 가자.」","mis":"K2-1-u5-X17"}],"explanation":["「뭘 그래」는 도윤이의 서운한 마음을 무시하는 말이에요.","다른 두 친구는 마음을 알아주는 맞장구를 쳤어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"나만 빼고 다 같이 놀러 갔대……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#22','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C3',3,'mc','auto','「하나도 안 무서워!」라고 말하면서 엄마 뒤에 꼭 숨었어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":22,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「하나도 안 무서워!」라고 말하면서 엄마 뒤에 꼭 숨었어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 안 무섭다고 했지만 사실은 무서운 마음","correct":true},{"t":"말 그대로 하나도 무섭지 않은 마음","mis":"K2-1-u5-X02"},{"t":"뿌듯하고 자랑스러운 마음","mis":"K2-1-u5-X03"}],"explanation":["엄마 뒤에 숨는 행동에서 무서운 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","다른 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#23','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#24','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C7',4,'essay','teacher','다음 문장에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 낱말의 뜻을 들어 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_b#25','kor',2,1,'u5','','g2_1_kor_u5_review_b','unit_review','K2-1-u5-C6',4,'essay','teacher','글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.","answer_guide":{"answer":"예: 처음에는 떨렸어요(다리가 후들후들). 다람쥐의 응원과 친구들의 손뼉 덕분에 끝에는 뿌듯했어요(가슴을 쭉 펴고 웃음).","scoring_points":["처음과 끝의 마음을 마음 말로 썼는가","마음이 바뀐 까닭을 글에서 찾아 썼는가","근거가 된 말이나 행동을 썼는가"]},"explanation":["처음과 끝의 마음.","바뀐 까닭.","근거."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#1','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C1',1,'mc','auto','말하지 않아도 친구의 마음을 알 수 있는 까닭은 무엇인가요?',ARRAY['K2-1-u5-X01']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"말하지 않아도 친구의 마음을 알 수 있는 까닭은 무엇인가요?","options":[{"t":"표정과 행동에 마음이 드러나니까","correct":true},{"t":"친구의 옷에 마음이 쓰여 있으니까","mis":"K2-1-u5-X01"},{"t":"친구의 이름에 마음이 들어 있으니까","mis":"K2-1-u5-X01"}],"explanation":["웃는 얼굴, 숙인 고개처럼 표정과 행동에 마음이 드러나요.","생김새·옷·이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#2','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C3',1,'mc','auto','눈을 동그랗게 뜨고 「와, 진짜?」 했어요. 이 인물의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"눈을 동그랗게 뜨고 「와, 진짜?」 했어요. 이 인물의 마음은 어느 것인가요?","options":[{"t":"놀란 마음","correct":true},{"t":"졸린 마음","mis":"K2-1-u5-X02"},{"t":"서운한 마음","mis":"K2-1-u5-X02"}],"explanation":["눈을 동그랗게 뜨고 「와, 진짜?」 한 말과 행동에서 놀란 마음이 드러나요.","다른 마음은 이 말·행동과 맞지 않아요.","행동을 따라 해 보며 마음을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#3','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"서운하다","correct":true},{"t":"가방","mis":"K2-1-u5-X05"},{"t":"학교","mis":"K2-1-u5-X05"}],"explanation":["「서운하다」는 마음을 나타내는 말이에요.","「가방」·「학교」는 물건·장소·움직임을 나타내요.","「나는 지금 ○○해.」에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#4','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「아빠가 / 방에 / 들어가신다」","correct":true},{"t":"「아 / 빠가방 / 에 들어가신다」","mis":"K2-1-u5-X11"},{"t":"「아빠가방에들어가신다」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#5','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',1,'mc','auto','「마치다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「마치다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"하던 일을 끝내다","correct":true},{"t":"목표에 닿게 하다","mis":"K2-1-u5-X09"},{"t":"몸에 상처를 입다","mis":"K2-1-u5-X09"}],"explanation":["「마치다」는 하던 일을 끝내다는 뜻이에요.","다른 뜻은 소리가 같거나 비슷한 다른 낱말의 뜻이에요.","소리가 같아도 뜻을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#6','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C8',1,'ox','auto','문장과 문장 사이에서는 문장 안에서보다 조금 더 길게 쉬어 읽어요.',ARRAY['K2-1-u5-X14']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"문장과 문장 사이에서는 문장 안에서보다 조금 더 길게 쉬어 읽어요.","answer":"O","reason_options":[{"t":"한 문장이 끝났다는 것을 듣는 사람이 알 수 있으니까","correct":true},{"t":"문장 사이에서는 쉬지 않고 이어 읽어야 하니까","mis":"K2-1-u5-X14"}],"mis":"K2-1-u5-X14","explanation":["문장이 끝나면 조금 더 길게 쉬어요.","뜻이 통하는 덩어리로 묶어 읽어요.","그러면 물 흐르듯 자연스럽게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#7','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C9',1,'mc','auto','인물이 떨리는 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 떨리는 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"작고 조심스럽게","correct":true},{"t":"크고 신나게","mis":"K2-1-u5-X15"},{"t":"화난 목소리로 세게","mis":"K2-1-u5-X15"}],"explanation":["인물이 떨리는 장면은 작고 조심스럽게 읽으면 마음이 살아나요.","다른 목소리는 이 장면의 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#8','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C10',1,'mc','auto','친구가 그림 대회에서 상을 받았어요. 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 그림 대회에서 상을 받았어요. 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「우아, 정말 축하해!」","correct":true},{"t":"「그게 뭐 대단해?」","mis":"K2-1-u5-X16"},{"t":"「나도 받을 수 있었어.」","mis":"K2-1-u5-X16"}],"explanation":["좋은 일이 생긴 친구에게는 축하하는 마음을 전해요.","마음이 담기지 않은 말이나 탓하는 말은 친구를 속상하게 해요.","마음 말로 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#9','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"친구가 약속을 잊어버렸을 때","r":"서운하다"},{"l":"처음으로 줄넘기 백 번을 넘었을 때","r":"뿌듯하다"},{"l":"하지 않은 일로 혼났을 때","r":"억울하다"}],"mis":"K2-1-u5-X03","explanation":["「친구가 약속을 잊어버렸을 때」 — 서운하다","「처음으로 줄넘기 백 번을 넘었을 때」 — 뿌듯하다","「하지 않은 일로 혼났을 때」 — 억울하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#10','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',2,'blank','auto','「약속은 (     ) 지킬게.」 빈칸에 알맞은 낱말은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「약속은 (     ) 지킬게.」 빈칸에 알맞은 낱말은 어느 것인가요?","options":[{"t":"반드시","correct":true},{"t":"반듯이","mis":"K2-1-u5-X09"},{"t":"반드기","mis":"K2-1-u5-X09"}],"explanation":["「틀림없이 꼭」이라는 뜻은 「반드시」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#11','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 우유가 쏟아진 뒤부터 지우의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":11,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 우유가 쏟아진 뒤부터 지우의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하다 → 따뜻하다","correct":true},{"t":"따뜻하다 → 속상하다","mis":"K2-1-u5-X07"},{"t":"속상하다 → 속상하다","mis":"K2-1-u5-X07"}],"explanation":["우유가 쏟아져 속상했다가, 할머니가 웃으셔서 마음이 따뜻해졌어요.","차례를 뒤바꾸거나 마음이 그대로라고 보면 안 돼요.","처음 → 무슨 일 → 나중을 따라가요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#12','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 지안이가 무서운 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":12,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 지안이가 무서운 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"엄마 손을 꼭 잡았어요","correct":true},{"t":"깔깔 웃었어요","mis":"K2-1-u5-X02"},{"t":"수영장에 갔어요","mis":"K2-1-u5-X08"}],"explanation":["엄마 손을 꼭 잡은 행동에 무서운 마음이 드러나요.","다른 마음이 드러난 부분이나 일어난 일과 헷갈리지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["지안이는 수영장 물을 보고 엄마 손을 꼭 잡았어요.","「물이 너무 깊어 보여…….」","그때 하람이가 「같이 손잡고 들어가자!」 하고 웃었어요.","지안이는 조심조심 물에 발을 담갔어요.","조금 지나자 첨벙첨벙 물장구를 치며 깔깔 웃었어요."],"title":"처음 간 수영장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#13','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',2,'ox','auto','「쌍둥이 형제는 얼굴이 조금 틀려요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":13,"concept":"K2-1-u5-C7","difficulty":2,"kind":"ox","stem":"「쌍둥이 형제는 얼굴이 조금 틀려요.」는 바르게 쓴 문장이에요.","answer":"X","reason_options":[{"t":"같지 않은 것은 「다르다」라서 「달라요」라고 써야 하니까","correct":true},{"t":"「틀리다」와 「다르다」는 뜻이 같으니까","mis":"K2-1-u5-X10"}],"mis":"K2-1-u5-X10","explanation":["같지 않은 것은 「다르다」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#14','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C8',2,'mc','auto','「작은 새가 나뭇가지에 앉았다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":14,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「작은 새가 나뭇가지에 앉았다.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「작은 새가 / 나뭇가지에 / 앉았다」","correct":true},{"t":"「작은 / 새 / 가 / 나뭇 / 가지에 앉았다」","mis":"K2-1-u5-X11"},{"t":"「작은 새가 나뭇 / 가지에 앉 / 았다」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","낱말 가운데에서 끊거나 덩어리를 흩뜨리면 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#15','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C10',2,'mc','auto','친구가 「줄넘기 백 번 넘었어!」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":15,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「줄넘기 백 번 넘었어!」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「우아, 정말 대단하다!」","correct":true},{"t":"「나도 그 정도는 해.」","mis":"K2-1-u5-X16"},{"t":"「그게 뭐 어려워?」","mis":"K2-1-u5-X16"}],"explanation":["친구의 기쁜 마음을 함께 나누는 말이에요.","친구의 마음을 가볍게 넘기거나 놀리는 말은 친구를 더 속상하게 해요.","내가 그 말을 들으면 어떨지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#16','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C5',2,'match','auto','마음을 나타내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"마음을 나타내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"억울하다","r":"잘못이 없는데 탓을 들어 답답하다"},{"l":"아쉽다","r":"바라던 일이 안 되어 서운하고 안타깝다"},{"l":"떨리다","r":"긴장되어 가슴이 두근두근하다"}],"mis":"K2-1-u5-X06","explanation":["「억울하다」 — 잘못이 없는데 탓을 들어 답답하다","「아쉽다」 — 바라던 일이 안 되어 서운하고 안타깝다","「떨리다」 — 긴장되어 가슴이 두근두근하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#17','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X09','K2-1-u5-X17']::text[],false,'{"seq":17,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"태민 — 「계단에서 넘어져 무릎을 닫혔어요.」","correct":true,"mis_target":"K2-1-u5-X09"},{"t":"은솔 — 「바람에 창문이 닫혔어요.」","mis":"K2-1-u5-X17"},{"t":"아린 — 「공으로 깡통을 맞혔어요.」","mis":"K2-1-u5-X17"}],"explanation":["몸에 상처를 입은 것은 「다쳤어요」라고 써야 해요.","다른 두 친구는 뜻에 맞게 바르게 썼어요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#18','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C6',3,'error','auto','글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],false,'{"seq":18,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"하늘 — 「지우는 끝까지 속상한 마음이 그대로였어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"민지 — 「우유가 쏟아져 눈물이 핑 돌았어.」","mis":"K2-1-u5-X17"},{"t":"지후 — 「할머니가 웃으셔서 마음이 따뜻해졌어.」","mis":"K2-1-u5-X17"}],"explanation":["지우의 마음은 할머니가 웃으시자 따뜻해졌어요.","마음은 처음 그대로 있지 않고 일에 따라 바뀌었어요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#19','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C8',3,'mc','auto','「작은 / 새와 나무」로 띄어 읽으면 작은 것은 무엇인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":19,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"「작은 / 새와 나무」로 띄어 읽으면 작은 것은 무엇인가요?","options":[{"t":"새와 나무 모두","correct":true},{"t":"새만","mis":"K2-1-u5-X13"},{"t":"나무만","mis":"K2-1-u5-X13"}],"explanation":["「작은 / 새와 나무」는 새와 나무가 모두 작다는 뜻이에요.","어디에서 쉬느냐에 따라 뜻이 달라져요.","끊어 읽은 대로 그림을 떠올려 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#20','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C4',3,'mc','auto','「달리기에서 하린이가 일 등, 준우가 꼴찌를 했어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":20,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"「달리기에서 하린이가 일 등, 준우가 꼴찌를 했어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"하린이는 기쁘고, 준우는 아쉬워요","correct":true},{"t":"하린이는 아쉽고, 준우는 기뻐요","mis":"K2-1-u5-X04"},{"t":"하린이는 미안하고, 준우는 설레요","mis":"K2-1-u5-X03"}],"explanation":["일 등을 한 하린이는 기쁘고, 꼴찌를 한 준우는 아쉬울 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#21','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C10',3,'error','auto','친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],false,'{"seq":21,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"현우 — 「강아지는 원래 자주 아파.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"예린 — 「많이 걱정되겠다.」","mis":"K2-1-u5-X17"},{"t":"도담 — 「강아지가 얼른 나으면 좋겠다.」","mis":"K2-1-u5-X17"}],"explanation":["「원래 자주 아파.」는 하준이의 걱정하는 마음을 알아주지 않아요.","다른 두 친구는 마음을 알아주는 맞장구를 쳤어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"우리 강아지가 아파서 병원에 갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#22','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C3',3,'mc','auto','「난 안 가도 돼.」라고 말하면서 친구들이 가는 쪽을 자꾸 돌아보았어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":22,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「난 안 가도 돼.」라고 말하면서 친구들이 가는 쪽을 자꾸 돌아보았어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 괜찮다고 했지만 사실은 같이 가고 싶은 마음","correct":true},{"t":"말 그대로 전혀 가고 싶지 않은 마음","mis":"K2-1-u5-X02"},{"t":"화가 나서 싸우고 싶은 마음","mis":"K2-1-u5-X03"}],"explanation":["자꾸 돌아보는 행동에서 같이 가고 싶은 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","다른 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#23','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#24','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C7',4,'essay','teacher','다음 문장에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 낱말의 뜻을 들어 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_c#25','kor',2,1,'u5','','g2_1_kor_u5_review_c','unit_review','K2-1-u5-C6',4,'essay','teacher','글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.","answer_guide":{"answer":"예: 처음에는 속상했어요(눈물이 핑 돎). 동생과 카드를 다시 만들어 드렸더니 할머니가 웃으셔서 끝에는 마음이 따뜻했어요.","scoring_points":["처음과 끝의 마음을 마음 말로 썼는가","마음이 바뀐 까닭을 글에서 찾아 썼는가","근거가 된 말이나 행동을 썼는가"]},"explanation":["처음과 끝의 마음.","바뀐 까닭.","근거."],"asset":{"type":"passage","lines":["지우는 할머니 생신 선물로 카드를 만들었어요.","그런데 동생이 카드에 우유를 쏟았어요.","지우는 눈물이 핑 돌았어요.","동생은 고개를 숙이고 「언니, 미안해.」 했어요.","둘이 함께 카드를 다시 만들어 드렸더니,","할머니가 활짝 웃으셨어요. 지우는 마음이 따뜻해졌어요."],"title":"할머니 생신 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#1','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C1',1,'mc','auto','글 속 인물의 마음을 짐작할 때 찾아야 할 것은 무엇인가요?',ARRAY['K2-1-u5-X01']::text[],false,'{"seq":1,"concept":"K2-1-u5-C1","difficulty":1,"kind":"mc","stem":"글 속 인물의 마음을 짐작할 때 찾아야 할 것은 무엇인가요?","options":[{"t":"마음이 드러난 말과 행동","correct":true},{"t":"인물의 옷차림","mis":"K2-1-u5-X01"},{"t":"글의 제목 글자 수","mis":"K2-1-u5-X01"}],"explanation":["「드디어 됐다!」 같은 말과 두 손을 번쩍 드는 행동에 마음이 드러나요.","생김새·옷·이름은 마음을 알려 주지 않아요.","무엇을 보고 알았는지 까닭을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#2','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C3',1,'mc','auto','주먹을 꽉 쥐고 「내가 안 그랬어!」 했어요. 이 인물의 마음은 어느 것인가요?',ARRAY['K2-1-u5-X02']::text[],false,'{"seq":2,"concept":"K2-1-u5-C3","difficulty":1,"kind":"mc","stem":"주먹을 꽉 쥐고 「내가 안 그랬어!」 했어요. 이 인물의 마음은 어느 것인가요?","options":[{"t":"억울한 마음","correct":true},{"t":"고마운 마음","mis":"K2-1-u5-X02"},{"t":"설레는 마음","mis":"K2-1-u5-X02"}],"explanation":["주먹을 쥐고 「내가 안 그랬어!」 한 말과 행동에서 억울한 마음이 드러나요.","다른 마음은 이 말·행동과 맞지 않아요.","행동을 따라 해 보며 마음을 느껴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#3','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C5',1,'mc','auto','마음을 나타내는 말은 어느 것인가요?',ARRAY['K2-1-u5-X05']::text[],false,'{"seq":3,"concept":"K2-1-u5-C5","difficulty":1,"kind":"mc","stem":"마음을 나타내는 말은 어느 것인가요?","options":[{"t":"고맙다","correct":true},{"t":"칠판","mis":"K2-1-u5-X05"},{"t":"걷다","mis":"K2-1-u5-X05"}],"explanation":["「고맙다」는 마음을 나타내는 말이에요.","「칠판」·「걷다」는 물건·장소·움직임을 나타내요.","「나는 지금 ○○해.」에 넣어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#4','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C2',1,'mc','auto','뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X12']::text[],false,'{"seq":4,"concept":"K2-1-u5-C2","difficulty":1,"kind":"mc","stem":"뜻이 잘 드러나게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「토끼가 / 풀밭에서 / 놀아요」","correct":true},{"t":"「토 / 끼가풀 / 밭에서 놀아요」","mis":"K2-1-u5-X11"},{"t":"「토끼가풀밭에서놀아요」","mis":"K2-1-u5-X12"}],"explanation":["뜻이 통하는 덩어리 사이에서 쉬어 읽었어요.","낱말 가운데에서 끊으면 뜻이 드러나지 않아요.","쉬지 않고 붙여 읽으면 알아듣기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#5','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',1,'mc','auto','「반드시」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X09']::text[],false,'{"seq":5,"concept":"K2-1-u5-C7","difficulty":1,"kind":"mc","stem":"「반드시」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"틀림없이 꼭","correct":true},{"t":"비뚤어지지 않고 곧게","mis":"K2-1-u5-X09"},{"t":"아주 천천히","mis":"K2-1-u5-X09"}],"explanation":["「반드시」는 틀림없이 꼭는 뜻이에요.","다른 뜻은 소리가 같거나 비슷한 다른 낱말의 뜻이에요.","소리가 같아도 뜻을 보고 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#6','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C8',1,'ox','auto','띄어 읽을 곳에 그은 빗금(/)에서는 쉬지 않고 붙여 읽어요.',ARRAY['K2-1-u5-X14']::text[],false,'{"seq":6,"concept":"K2-1-u5-C8","difficulty":1,"kind":"ox","stem":"띄어 읽을 곳에 그은 빗금(/)에서는 쉬지 않고 붙여 읽어요.","answer":"X","reason_options":[{"t":"빗금은 조금 쉬어 읽으라는 표시이니까","correct":true},{"t":"빗금은 빠르게 읽으라는 표시이니까","mis":"K2-1-u5-X14"}],"mis":"K2-1-u5-X14","explanation":["빗금이 있는 곳에서 조금 쉬어 읽어요.","뜻이 통하는 덩어리로 묶어 읽어요.","그러면 물 흐르듯 자연스럽게 들려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#7','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C9',1,'mc','auto','인물이 고마워하는 장면을 읽을 때 알맞은 목소리는 어느 것인가요?',ARRAY['K2-1-u5-X15']::text[],false,'{"seq":7,"concept":"K2-1-u5-C9","difficulty":1,"kind":"mc","stem":"인물이 고마워하는 장면을 읽을 때 알맞은 목소리는 어느 것인가요?","options":[{"t":"따뜻하고 다정하게","correct":true},{"t":"거칠고 퉁명스럽게","mis":"K2-1-u5-X15"},{"t":"졸린 듯 작게","mis":"K2-1-u5-X15"}],"explanation":["인물이 고마워하는 장면은 따뜻하고 다정하게 읽으면 마음이 살아나요.","다른 목소리는 이 장면의 마음과 맞지 않아요.","인물의 마음을 먼저 말하고 목소리를 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#8','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',1,'mc','auto','친구가 빌려 간 책을 돌려주지 않아 서운해요. 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":8,"concept":"K2-1-u5-C10","difficulty":1,"kind":"mc","stem":"친구가 빌려 간 책을 돌려주지 않아 서운해요. 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「책을 안 돌려줘서 조금 서운했어.」","correct":true},{"t":"「너 정말 나빠!」","mis":"K2-1-u5-X16"},{"t":"「몰라, 됐어.」","mis":"K2-1-u5-X16"}],"explanation":["무슨 일 때문에 어떤 마음인지 마음 말로 전해요.","마음이 담기지 않은 말이나 탓하는 말은 친구를 속상하게 해요.","마음 말로 정확히 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#9','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C4',2,'match','auto','상황과 어울리는 마음을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K2-1-u5-C4","difficulty":2,"kind":"match","stem":"상황과 어울리는 마음을 알맞게 이어 보세요.","pairs":[{"l":"기다리던 소풍이 비로 미뤄졌을 때","r":"아쉽다"},{"l":"새 반에서 아는 친구가 하나도 없을 때","r":"어색하다"},{"l":"친구와 함께 깔깔 웃으며 놀 때","r":"즐겁다"}],"mis":"K2-1-u5-X03","explanation":["「기다리던 소풍이 비로 미뤄졌을 때」 — 아쉽다","「새 반에서 아는 친구가 하나도 없을 때」 — 어색하다","「친구와 함께 깔깔 웃으며 놀 때」 — 즐겁다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#10','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',2,'blank','auto','「놀이터에서 장갑을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X09']::text[],false,'{"seq":10,"concept":"K2-1-u5-C7","difficulty":2,"kind":"blank","stem":"「놀이터에서 장갑을 (     ).」 빈칸에 알맞은 말은 어느 것인가요?","options":[{"t":"잃어버렸어요","correct":true},{"t":"잊어버렸어요","mis":"K2-1-u5-X10"},{"t":"잇어버렸어요","mis":"K2-1-u5-X09"}],"explanation":["가졌던 물건이 없어진 것은 「잃어버렸어요」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#11','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C6',2,'mc','auto','글을 읽고 답해 보세요. 서준이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X07']::text[],false,'{"seq":11,"concept":"K2-1-u5-C6","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 서준이의 마음이 바뀐 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"속상하다 → 뿌듯하다","correct":true},{"t":"뿌듯하다 → 속상하다","mis":"K2-1-u5-X07"},{"t":"속상하다 → 속상하다","mis":"K2-1-u5-X07"}],"explanation":["비행기가 떨어져 속상했다가, 끝까지 날아가자 뿌듯했어요.","차례를 뒤바꾸거나 마음이 그대로라고 보면 안 돼요.","처음 → 무슨 일 → 나중을 따라가요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#12','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C3',2,'mc','auto','글을 읽고 답해 보세요. 아기 곰이 뿌듯한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X08']::text[],false,'{"seq":12,"concept":"K2-1-u5-C3","difficulty":2,"kind":"mc","stem":"글을 읽고 답해 보세요. 아기 곰이 뿌듯한 마음이었다는 것을 알 수 있는 부분은 어느 것인가요?","options":[{"t":"가슴을 쭉 펴고 환하게 웃었어요","correct":true},{"t":"다리가 후들후들 떨렸어요","mis":"K2-1-u5-X02"},{"t":"음악회에서 북을 치기로 했어요","mis":"K2-1-u5-X08"}],"explanation":["가슴을 쭉 펴고 웃는 행동에 뿌듯한 마음이 드러나요.","다른 마음이 드러난 부분이나 일어난 일과 헷갈리지 않아요.","마음이 드러난 말과 행동을 찾아요."],"asset":{"type":"passage","lines":["아기 곰이 숲속 음악회에서 북을 치기로 했어요.","무대 뒤에서 다리가 후들후들 떨렸어요.","다람쥐가 「넌 잘할 수 있어!」 하고 어깨를 토닥였어요.","둥둥둥, 북소리가 숲에 울리자 친구들이 손뼉을 쳤어요.","아기 곰은 가슴을 쭉 펴고 환하게 웃었어요."],"title":"숲속 음악회"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#13','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',2,'ox','auto','「꼭 이기기를 바라요.」는 바르게 쓴 문장이에요.',ARRAY['K2-1-u5-X10']::text[],false,'{"seq":13,"concept":"K2-1-u5-C7","difficulty":2,"kind":"ox","stem":"「꼭 이기기를 바라요.」는 바르게 쓴 문장이에요.","answer":"O","reason_options":[{"t":"이루어지기를 원하는 것은 「바라다」니까","correct":true},{"t":"「바래요」라고 써야 맞으니까","mis":"K2-1-u5-X10"}],"mis":"K2-1-u5-X10","explanation":["원하는 것은 「바라다」라서 「바라요」예요.","소리가 같거나 비슷해도 뜻이 달라요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#14','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C8',2,'mc','auto','「엄마가 시장에서 사과를 사 오셨어요.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?',ARRAY['K2-1-u5-X11','K2-1-u5-X13']::text[],false,'{"seq":14,"concept":"K2-1-u5-C8","difficulty":2,"kind":"mc","stem":"「엄마가 시장에서 사과를 사 오셨어요.」를 자연스럽게 띄어 읽은 것은 어느 것인가요?","options":[{"t":"「엄마가 / 시장에서 / 사과를 사 오셨어요」","correct":true},{"t":"「엄 / 마가 / 시 / 장에서 / 사과를 사 오셨어요」","mis":"K2-1-u5-X11"},{"t":"「엄마가시 / 장에서사과를 / 사 오셨어요」","mis":"K2-1-u5-X13"}],"explanation":["뜻이 통하는 덩어리로 묶어 띄어 읽었어요.","너무 잘게 끊으면 뜻이 끊겨 어색해요.","낱말 가운데에서 끊거나 덩어리를 흩뜨리면 뜻이 흐려져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#15','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',2,'mc','auto','친구가 「무서운 꿈을 꿨어.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X16']::text[],false,'{"seq":15,"concept":"K2-1-u5-C10","difficulty":2,"kind":"mc","stem":"친구가 「무서운 꿈을 꿨어.」라고 했어요. 마음을 헤아린 맞장구로 알맞은 것은 어느 것인가요?","options":[{"t":"「많이 놀랐겠다. 지금은 괜찮아?」","correct":true},{"t":"「겁쟁이네.」","mis":"K2-1-u5-X16"},{"t":"「꿈은 다 가짜야.」","mis":"K2-1-u5-X16"}],"explanation":["친구의 놀란 마음을 알아주는 말이에요.","친구의 마음을 가볍게 넘기거나 놀리는 말은 친구를 더 속상하게 해요.","내가 그 말을 들으면 어떨지 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#16','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C5',2,'match','auto','마음을 나타내는 말과 뜻을 알맞게 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"K2-1-u5-C5","difficulty":2,"kind":"match","stem":"마음을 나타내는 말과 뜻을 알맞게 이어 보세요.","pairs":[{"l":"외롭다","r":"혼자가 되어 쓸쓸하다"},{"l":"반갑다","r":"보고 싶던 사람을 만나 기쁘다"},{"l":"어색하다","r":"낯설어서 자연스럽지 못하다"}],"mis":"K2-1-u5-X06","explanation":["「외롭다」 — 혼자가 되어 쓸쓸하다","「반갑다」 — 보고 싶던 사람을 만나 기쁘다","「어색하다」 — 낯설어서 자연스럽지 못하다"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#17','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',3,'error','auto','받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?',ARRAY['K2-1-u5-X10','K2-1-u5-X17']::text[],false,'{"seq":17,"concept":"K2-1-u5-C7","difficulty":3,"kind":"error","stem":"받아쓰기를 했어요. 낱말을 잘못 쓴 친구는 누구인가요?","options":[{"t":"현우 — 「동생이 손가락으로 별을 가르쳤어요.」","correct":true,"mis_target":"K2-1-u5-X10"},{"t":"지안 — 「언니가 나에게 줄넘기를 가르쳐 주었어요.」","mis":"K2-1-u5-X17"},{"t":"서윤 — 「선생님께서 칠판을 가리키셨어요.」","mis":"K2-1-u5-X17"}],"explanation":["손가락으로 짚어 보인 것은 「가리켰어요」라고 써야 해요.","다른 두 친구는 뜻에 맞게 바르게 썼어요.","문장의 뜻을 생각하며 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#18','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C6',3,'error','auto','글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?',ARRAY['K2-1-u5-X07','K2-1-u5-X17']::text[],false,'{"seq":18,"concept":"K2-1-u5-C6","difficulty":3,"kind":"error","stem":"글을 읽고 인물의 마음을 말했어요. 글과 다르게 말한 친구는 누구인가요?","options":[{"t":"준우 — 「서준이는 처음부터 끝까지 속상하기만 했어.」","correct":true,"mis_target":"K2-1-u5-X07"},{"t":"하린 — 「비행기가 떨어질 때는 입술을 삐죽 내밀었어.」","mis":"K2-1-u5-X17"},{"t":"로아 — 「끝에는 「와, 해냈다!」 하며 손뼉을 쳤어.」","mis":"K2-1-u5-X17"}],"explanation":["서준이는 비행기가 끝까지 날아가자 뿌듯해했어요.","마음은 처음 그대로 있지 않고 일에 따라 바뀌었어요.","다른 두 친구는 글과 같게 말했어요."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#19','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C8',3,'mc','auto','「작은 새와 / 나무」로 띄어 읽으면 작은 것은 무엇인가요?',ARRAY['K2-1-u5-X13']::text[],false,'{"seq":19,"concept":"K2-1-u5-C8","difficulty":3,"kind":"mc","stem":"「작은 새와 / 나무」로 띄어 읽으면 작은 것은 무엇인가요?","options":[{"t":"새만","correct":true},{"t":"새와 나무 모두","mis":"K2-1-u5-X13"},{"t":"나무만","mis":"K2-1-u5-X13"}],"explanation":["「작은 새와 / 나무」는 새만 작다는 뜻이에요.","어디에서 쉬느냐에 따라 뜻이 달라져요.","끊어 읽은 대로 그림을 떠올려 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#20','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C4',3,'mc','auto','「지호가 짝에게 연필을 빌려주었어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?',ARRAY['K2-1-u5-X04','K2-1-u5-X03']::text[],false,'{"seq":20,"concept":"K2-1-u5-C4","difficulty":3,"kind":"mc","stem":"「지호가 짝에게 연필을 빌려주었어요.」 두 사람의 마음을 바르게 짐작한 것은 어느 것인가요?","options":[{"t":"짝은 고맙고, 지호는 뿌듯해요","correct":true},{"t":"짝은 뿌듯하고, 지호는 고마워요","mis":"K2-1-u5-X04"},{"t":"짝은 억울하고, 지호는 서운해요","mis":"K2-1-u5-X03"}],"explanation":["빌린 짝은 고맙고, 도와준 지호는 뿌듯할 거예요.","같은 일이라도 사람마다 마음이 다를 수 있어요.","누가 어떤 일을 겪었는지 나누어 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#21','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C10',3,'error','auto','친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?',ARRAY['K2-1-u5-X16','K2-1-u5-X17']::text[],false,'{"seq":21,"concept":"K2-1-u5-C10","difficulty":3,"kind":"error","stem":"친구의 말을 듣고 대답했어요. 친구의 마음을 헤아리지 않고 대답한 친구는 누구인가요?","options":[{"t":"준우 — 「잘됐네, 내 자리가 넓어지겠다.」","correct":true,"mis_target":"K2-1-u5-X16"},{"t":"서아 — 「많이 섭섭하다.」","mis":"K2-1-u5-X17"},{"t":"하늘 — 「가서도 꼭 연락하자.」","mis":"K2-1-u5-X17"}],"explanation":["「내 자리가 넓어지겠다」는 소율이의 섭섭한 마음을 생각하지 않은 말이에요.","다른 두 친구는 마음을 알아주는 맞장구를 쳤어요.","내가 그 말을 들으면 어떨지 떠올려요."],"asset":{"type":"speech","turns":[{"who":"소율","text":"내일 이사 가서 전학 가."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#22','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C3',3,'mc','auto','「별로 안 기뻐.」라고 말하면서 입가에 웃음이 번졌어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K2-1-u5-X02','K2-1-u5-X03']::text[],false,'{"seq":22,"concept":"K2-1-u5-C3","difficulty":3,"kind":"mc","stem":"「별로 안 기뻐.」라고 말하면서 입가에 웃음이 번졌어요. 이 인물의 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말은 안 기쁘다고 했지만 사실은 기쁜 마음","correct":true},{"t":"말 그대로 하나도 안 기쁜 마음","mis":"K2-1-u5-X02"},{"t":"무섭고 떨리는 마음","mis":"K2-1-u5-X03"}],"explanation":["입가에 웃음이 번지는 모습에서 기쁜 마음이 드러나요.","말만 보지 말고 행동도 함께 살펴요.","다른 마음은 이 장면과 맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#23','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C9',4,'mc','auto','다음 글을 읽는 방법으로 가장 알맞은 것은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#24','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C7',4,'essay','teacher','다음 문장에서 잘못 쓴 낱말을 찾아 바르게 고쳐 쓰고, 그렇게 고친 까닭을 낱말의 뜻을 들어 써 보세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_1_kor_u5_review_d#25','kor',2,1,'u5','','g2_1_kor_u5_review_d','unit_review','K2-1-u5-C6',4,'essay','teacher','글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"K2-1-u5-C6","difficulty":4,"kind":"essay","stem":"글을 읽고 답해 보세요. 인물의 마음이 처음과 끝에 어떠했는지 마음 말로 쓰고, 마음이 바뀐 까닭과 그렇게 짐작한 근거(말이나 행동)를 써 보세요.","answer_guide":{"answer":"예: 처음에는 속상했어요(입술을 삐죽 내밂). 다시 접어 날린 비행기가 끝까지 날아가서 끝에는 뿌듯했어요(「와, 해냈다!」 하며 손뼉).","scoring_points":["처음과 끝의 마음을 마음 말로 썼는가","마음이 바뀐 까닭을 글에서 찾아 썼는가","근거가 된 말이나 행동을 썼는가"]},"explanation":["처음과 끝의 마음.","바뀐 까닭.","근거."],"asset":{"type":"passage","lines":["서준이는 종이비행기를 접었어요.","날려 보았지만 몇 번이나 바닥에 툭 떨어졌어요.","서준이는 입술을 삐죽 내밀었어요.","날개를 다시 반듯이 접어 힘껏 날렸더니,","비행기가 교실 끝까지 날아갔어요.","서준이는 「와, 해냈다!」 하며 손뼉을 쳤어요."],"title":"종이비행기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
